const statusArabic = {PENDING:'بانتظار المراجعة',APPROVED:'معتمد',FULL_CORRECTION:'تصحيح كامل',DIALECT_CORRECTION:'تصحيح اللهجة',CONTENT_CORRECTION:'تصحيح المحتوى',IGNORED:'تم تجاهلها',DELETED:'محذوفة'};
const tagArabic = {forgot_previous_constraint:'نسي قيدًا سابقًا',ignored_user_instruction:'تجاهل تعليمات المستخدم',wrong_context:'سياق خاطئ',repeated_rejected_option:'كرر خيارًا مرفوضًا',contradiction:'تناقض',instruction_following:'اتباع التعليمات',constraint_failure:'إخفاق في القيود',context_failure:'إخفاق في فهم السياق',tool_behavior:'سلوك الأدوات',repetition:'تكرار',verbosity:'إطالة',formatting:'تنسيق',safety:'سلامة',hallucination:'هلوسة',dialect_issue:'مشكلة لهجة',grammar_issue:'مشكلة نحوية',unnatural_arabic:'عربية غير طبيعية',too_verbose:'مطوّل',too_short:'قصير جدًا',format_failure:'خطأ تنسيق',factual_error:'خطأ واقعي',other:'أخرى'};
const $ = (selector) => document.querySelector(selector);
const $$ = (selector,root=document) => [...root.querySelectorAll(selector)];
const esc = (value='') => String(value ?? '').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const compact = (value='', max=130) => String(value ?? '').length > max ? `${String(value).slice(0,max)}…` : String(value ?? '');
const fmtDate = (value) => value ? new Intl.DateTimeFormat('ar-SA',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value)) : '—';
const uiStatus = (value) => window.NajdiI18n?.status(value) || String(value || 'غير معروف');

async function api(path, options={}) {
  const response = await fetch(path, {headers:{'Content-Type':'application/json',...(options.headers||{})},...options});
  let payload;
  try { payload = await response.json(); } catch { payload = {error:'استجابة غير صالحة من الخادم'}; }
  if (!response.ok) throw new Error(payload.message || payload.error || `HTTP ${response.status}`);
  return payload;
}

function toast(message, error=false) {
  const el = $('#toast'); el.textContent = message; el.className = `toast show${error?' error':''}`;
  clearTimeout(toast.timer); toast.timer = setTimeout(()=>el.className='toast', 2800);
}

const viewPaths={dashboard:'/',conversations:'/conversations','review-queue':'/review','reviewed':'/gold','add-data':'/data/add','manual-data':'/data/manual',dataset:'/datasets/gold','dataset-health':'/datasets/health',balancer:'/datasets/balancer','dataset-versions':'/datasets/versions',training:'/training/setup','training-jobs':'/training/jobs','eval-sets':'/datasets/eval','human-review':'/evaluation/human-review','phase38-review':'/evaluation/remediation-review','phase39-review':'/evaluation/remediation-review-edits',exports:'/exports',analytics:'/analytics',settings:'/settings'};
const pathViews=Object.fromEntries(Object.entries(viewPaths).map(([view,path])=>[path,view]));
function selectedVersion(){return new URLSearchParams(location.search).get('version')||state.selectedDataset||'';}
function updateLocation(view,version='',replace=false){const path=viewPaths[view]||'/';const query=version?`?version=${encodeURIComponent(version)}`:'';(replace?history.replaceState:history.pushState).call(history,{view,version},'',path+query);}
function switchView(view,options={}) {
  if(!titles[view])view='dashboard';
  if(state.view==='phase38-review'&&view!==state.view&&state.phase38Dirty&&!confirm('لديك تغييرات غير محفوظة في سجل المعالجة. هل تريد مغادرة الصفحة وفقدها؟'))return;
  state.view = view;
  $$('.nav-item').forEach(b=>b.classList.toggle('active', b.dataset.view===view));
  $$('.view').forEach(v=>v.classList.toggle('active', v.id===`view-${view}`));
  $('#page-title').textContent = titles[view][0]; $('#page-subtitle').textContent = titles[view][1];
  $('#page-breadcrumb').textContent = view==='dataset-health'?'Datasets > Health':view==='balancer'?'Datasets > Balancer':`NajdiLab / ${titles[view][0]}`;
  if(view==='dataset-health')$('#page-subtitle').textContent='فحص جودة وتوازن وسلامة إصدار Dataset';
  $('.sidebar').classList.remove('open');
  if(!options.fromHistory)updateLocation(view,options.version||selectedVersion(),options.replace);
  loadView(view).catch(error=>toast(error.message,true));
}

async function loadView(view) {
  if (view==='dashboard') return loadDashboard();
  if (view==='review-queue') return loadQueue();
  if (view==='conversations') return loadConversations();
  if (view==='reviewed') return loadReviewed();
  if (view==='manual-data') return loadManualData();
  if (view==='dataset') return loadDataset();
  if (view==='dataset-health') return loadHealth();
  if (view==='balancer') return loadBalancer();
  if (view==='dataset-versions') return loadDatasetVersions();
  if (view==='training') return loadTrainingSetup();
  if (view==='training-jobs') return loadTrainingJobs();
  if (view==='eval-sets') return loadEvalSets();
  if (view==='human-review') return loadPhase3Review();
  if (view==='phase38-review') return loadPhase38Review();
  if (view==='phase39-review') return loadPhase39Verification();
  if (view==='exports') return loadExports();
  if (view==='analytics') return loadAnalytics();
}

async function loadPhase39Verification(){const host=$('#phase39-status'),list=$('#phase39-records');try{const data=await api('/api/v1/phase39/post-edit-verification');state.phase39=data;state.phase39Index=Math.min(state.phase39Index||0,data.records.length-1);$('#nav-phase39').textContent=`${data.summary.verified}/${data.summary.total}`;renderPhase39Verification();}catch(e){host.textContent=`تعذر تحميل حالة التحقق: ${e.message}`;host.className='phase38-status error-state';}}
function renderPhase39Verification(){const data=state.phase39,r=data.records[state.phase39Index],host=$('#phase39-status'),list=$('#phase39-records');host.textContent=`التقدم: ${data.summary.verified}/${data.summary.total} · السجل ${state.phase39Index+1} من 7`;list.innerHTML=`<article class="phase38-message"><b class="technical-id">${esc(r.record_id)}</b><p>${esc(r.record_type)} · ${esc(r.validation_status)} · contamination: ${esc(r.contamination_status||'PASS')} · loss-mask: ${esc(r.loss_mask_status||'PASS')}</p><h4>الرد الأصلي</h4><p>${esc(r.original_assistant_messages)}</p><h4>ملاحظة المراجع</h4><p>${esc(r.reviewer_note)}</p><h4>التعديل المطلوب</h4><p>${esc(r.requested_correction)}</p><h4>النسخة المطبقة</h4><p>${esc(r.final_assistant_messages)}</p>${r.record_type==='native_tool_use'?'<p>استدعاء الأداة والنتيجة السلطوية وبيانات السجل محمية للقراءة فقط.</p>':''}</article><label class="wide-label">ملاحظة التحقق<textarea id="phase39-reviewer-note" rows="3">${esc(r.post_edit_note||'')}</textarea></label><div class="phase38-decisions"><button class="button ghost" data-phase39-decision="اعتماد التعديل">اعتماد التعديل</button><button class="button ghost" data-phase39-decision="يحتاج تعديل إضافي">يحتاج تعديل إضافي</button><button class="button ghost" data-phase39-decision="رفض">رفض</button></div><div class="save-row"><button class="button ghost" data-phase39-nav="prev">السابق</button><button class="button primary" id="phase39-save">حفظ</button><button class="button ghost" data-phase39-nav="next">التالي</button></div>`;$$('[data-phase39-decision]').forEach(b=>b.classList.toggle('selected',b.dataset.phase39Decision===r.decision));bindPhase39Verification();}
function bindPhase39Verification(){const root=$('#view-phase39-review');root.onclick=async e=>{const nav=e.target.closest('[data-phase39-nav]'),decision=e.target.closest('[data-phase39-decision]');if(nav){state.phase39Index=Math.max(0,Math.min(6,state.phase39Index+(nav.dataset.phase39Nav==='next'?1:-1)));renderPhase39Verification();return;}if(decision){state.phase39Decision=decision.dataset.phase39Decision;$$('[data-phase39-decision]').forEach(b=>b.classList.toggle('selected',b===decision));return;}if(!e.target.closest('#phase39-save'))return;if(!state.phase39Decision){toast('اختر قرار التحقق أولًا',true);return;}const r=state.phase39.records[state.phase39Index];try{const out=await api(`/api/v1/phase39/post-edit-verification/${encodeURIComponent(r.record_id)}`,{method:'POST',body:JSON.stringify({decision:state.phase39Decision,reviewer_note:$('#phase39-reviewer-note').value})});state.phase39=out.verification;state.phase39Decision=null;toast('تم حفظ التحقق بنجاح.');renderPhase39Verification();}catch(err){toast(`تعذر الحفظ: ${err.message}`,true);}};}

async function ensureDatasetVersions(){
  if(!state.datasetVersions.length){const data=await api('/api/v1/dataset-versions');if(!Array.isArray(data.items))throw new Error('استجابة إصدارات Dataset غير صالحة');state.datasetVersions=data.items;}
  const preferred=state.datasetVersions.some(x=>x.version==='gold-v008-split-clean')?'gold-v008-split-clean':state.datasetVersions.some(x=>x.version==='gold-v007-balanced')?'gold-v007-balanced':state.datasetVersions[0]?.version;
  const requested=selectedVersion();state.selectedDataset=state.datasetVersions.some(x=>x.version===requested)?requested:preferred||'';
  ['#health-version','#balance-version','#eval-version'].forEach(selector=>{const select=$(selector);if(!select)return;select.innerHTML=state.datasetVersions.map(x=>`<option value="${esc(x.version)}" ${x.readable===false?'disabled':''}>${esc(x.version)}${x.readable===false?' — غير قابل للقراءة':''}</option>`).join('');select.value=state.selectedDataset;});
  return preferred;
}

function pct(value){return value==null?'—':`${(Number(value)*100).toFixed(2)}%`;}
function healthCard(title,status,value,description,detail){return `<button class="health-card" data-health-detail="${esc(detail)}"><span class="health-card-status ${String(status).toLowerCase()}">${esc(status)}</span><h3>${esc(title)}</h3><strong>${esc(value)}</strong><p>${esc(description)}</p><small>عرض التفاصيل</small></button>`;}
function showHealthError(message){$('#health-results').classList.add('hidden');$('#health-state').className='panel health-state error-state';$('#health-state').innerHTML=`<strong>تعذر فحص صحة Dataset</strong><p>${esc(message)}. لم يتم تعديل Dataset ويمكن إعادة المحاولة بأمان.</p><button id="health-retry" class="button primary">إعادة المحاولة</button>`;$('#health-retry').onclick=()=>loadHealth(true);}
async function loadHealth(force=false){
  $('#health-state').className='panel health-state';$('#health-state').textContent='جارٍ تحميل الإصدارات...';$('#health-results').classList.add('hidden');
  try{await ensureDatasetVersions();}catch(error){showHealthError(`تعذر تحميل إصدارات Dataset: ${error.message}`);return;}
  const select=$('#health-version'),button=$('#refresh-health');if(!state.datasetVersions.length){select.innerHTML='';button.disabled=true;$('#health-state').textContent='لا توجد إصدارات Dataset متاحة للفحص.';return;}
  const version=select.value||state.selectedDataset;select.value=version;button.disabled=false;state.selectedDataset=version;updateLocation('dataset-health',version,true);
  button.disabled=true;button.textContent=force?'جارٍ إعادة الفحص...':`جارٍ فحص ${version}...`;$('#health-state').textContent=`جارٍ فحص ${version}...`;
  try{const data=await api(`/api/v1/dataset-versions/${encodeURIComponent(version)}/health`);state.health=data;$('#health-state').classList.add('hidden');$('#health-results').classList.remove('hidden');$('#health-dataset').textContent=data.version;$('#health-timestamp').textContent=data.checked_at;$('#health-last-result').textContent=force?'نتيجة فحص جديدة':'Last Health Result';
    const tr=data.training_readiness,ei=data.evaluation_integrity;$('#health-summary').innerHTML=healthCard('Training Readiness',tr.status,tr.status,tr.training_errors?'توجد أخطاء خاصة بالتدريب.':'Schema وtargets وloss masks صالحة.','training')+healthCard('Evaluation Integrity',ei.status,ei.status,`${ei.conversation_overlap_count} conversation overlaps`,'evaluation')+healthCard('Training Records','INFO',data.training_count,`${data.counts['sft.jsonl']||0} SFT و${data.counts['multi_turn.jsonl']||0} Multi-turn`,'records')+healthCard('Warnings',data.warnings.length?'WARNING':'CLEAN',data.warnings.length,'تحذيرات قابلة للفحص دون تعديل المصدر.','warnings');
    const r=data.highest_record_share?.[1]||{},c=data.highest_context_word_share?.[1]||{},t=data.highest_target_word_share?.[1]||{};$('#health-checks').innerHTML=healthCard('Conversation Balance',r.record_share>.15?'WARNING':'CLEAN',pct(r.record_share),'أعلى حصة لسجلات محادثة واحدة.','balance')+healthCard('Duplicates',data.exact_duplicate_extra?'FAILED':'CLEAN',data.exact_duplicate_extra,'أهداف تدريب مطابقة زائدة.','duplicates')+healthCard('Language / Phrase Dominance','INFO',pct(data.longest_10_target_word_share),'حصة أطول عشرة أهداف.','phrases')+healthCard('Loss Masks',data.loss_mask_validation?.failures?.length?'FAILED':'CLEAN',`${data.loss_mask_validation?.passed??0}/${data.loss_mask_validation?.total??0}`,'تحقق الاستهداف النهائي.','masks')+healthCard('Leakage',ei.status,ei.conversation_overlap_count,'تداخل محادثات Eval مع Training.','evaluation');
    $('#health-warning-count').textContent=data.warnings.length;$('#health-warnings').innerHTML=data.warnings.length?data.warnings.map(x=>`<button class="health-warning ${x.level}" data-health-detail="${x.code}"><strong>${x.level==='error'?'خطأ':'تنبيه'}</strong><span>${esc(x.message)}</span></button>`).join(''):'<div class="success-state">لا توجد تحذيرات.</div>';
  }catch(error){showHealthError(error.message);}finally{button.disabled=false;button.textContent=force?'إعادة الفحص':'إعادة الفحص';}}

function showHealthDetail(kind){const d=state.health;if(!d)return;const r=d.highest_record_share?.[1]||{},c=d.highest_context_word_share?.[1]||{},t=d.highest_target_word_share?.[1]||{};const key=d.highest_record_share?.[0]||'—';const details={training:[['Status',d.training_readiness.status],['Invalid target indices',d.training_readiness.invalid_target_indices],['Invalid loss masks',d.training_readiness.invalid_loss_masks]],evaluation:[['Status',d.evaluation_integrity.status],['Conversation overlap',d.evaluation_integrity.conversation_overlap_count],['Exact target overlap',d.evaluation_integrity.exact_target_overlap_count],...d.evaluation_integrity.by_file.map(x=>[x.name,`${x.status} · ${x.conversation_overlap_count} overlap`])],balance:[['Conversation',key],['Records',r.total_records??'—'],['Record share',pct(r.record_share)],['Target-word share',pct(t.target_word_share)],['Context-word share',pct(c.context_word_share)]],conversation_concentration:[['Conversation',key],['Records',r.total_records??'—'],['Record share',pct(r.record_share)]],context_concentration:[['Conversation',d.highest_context_word_share?.[0]||'—'],['Context-word share',pct(c.context_word_share)]],phrases:[['Longest-10 target share',pct(d.longest_10_target_word_share)],...Object.entries(d.phrase_counts||{})],duplicates:[['Exact duplicate extra',d.exact_duplicate_extra]],masks:[['Passed',d.loss_mask_validation?.passed??0],['Total',d.loss_mask_validation?.total??0]],warnings:d.warnings.map(x=>[x.code,x.message]),records:[['SFT',d.counts['sft.jsonl']||0],['Multi-turn',d.counts['multi_turn.jsonl']||0],['Total',d.training_count]],eval_leakage:[['Conversation overlap',d.evaluation_integrity.conversation_overlap_count],['Exact target overlap',d.evaluation_integrity.exact_target_overlap_count]]};const rows=details[kind]||details.warnings;$('#health-detail-panel').classList.remove('hidden');$('#health-detail-panel').innerHTML=`<div class="panel-heading"><h2>تفاصيل الفحص</h2><button class="button ghost" data-close-health-detail>إغلاق</button></div><dl class="metric-list">${rows.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd class="technical-value">${esc(v)}</dd></div>`).join('')}</dl>`;$('#health-detail-panel').scrollIntoView({behavior:'smooth',block:'nearest'});}

function balanceBars(title,items,labels={}){const max=Math.max(1,...items.map(x=>x.count));return `<section class="panel phase-panel balance-panel"><h2>${esc(title)}</h2><div class="balance-bars">${items.length?items.map(x=>`<div class="balance-bar"><header><span>${esc(labels[x.name]||x.name)}</span><strong>${x.count} · ${pct(x.share)}</strong></header><div><i style="width:${x.count/max*100}%"></i></div></div>`).join(''):'<div class="empty-inline">لا توجد بيانات متاحة.</div>'}</div></section>`;}
function balanceMetricPanel(title,items){return `<section class="panel phase-panel balance-panel"><h2>${esc(title)}</h2><dl class="metric-list">${items.map(([key,value])=>`<div><dt>${esc(key)}</dt><dd class="technical-value">${esc(value)}</dd></div>`).join('')}</dl></section>`;}
function showBalanceError(message){$('#balance-results').classList.add('hidden');$('#balance-state').className='panel health-state error-state';$('#balance-state').innerHTML=`<strong>Unavailable</strong><p>${esc(message)}. بقي الإصدار ظاهرًا ولم يتم تعديل أي ملف.</p><button id="balance-retry" class="button primary">إعادة المحاولة</button>`;$('#balance-retry').onclick=()=>loadBalancer(true);}
async function loadBalancer(force=false){
  $('#balance-state').className='panel health-state';$('#balance-state').textContent='جارٍ تحميل إصدارات Dataset...';$('#balance-results').classList.add('hidden');
  try{await ensureDatasetVersions();}catch(error){showBalanceError(error.message);return;}
  const select=$('#balance-version'),button=$('#run-balance');if(!state.datasetVersions.length){select.innerHTML='';button.disabled=true;$('#balance-state').textContent='لا توجد إصدارات Dataset.';return;}
  const version=select.value||state.selectedDataset;select.value=version;state.selectedDataset=version;updateLocation('balancer',version,true);button.disabled=true;button.textContent='جارٍ التحليل...';
  try{const data=await api(`/api/v1/dataset-versions/${encodeURIComponent(version)}/balance`);state.balance=data;$('#balance-state').classList.add('hidden');$('#balance-results').classList.remove('hidden');$('#balance-dataset').textContent=data.version;$('#balance-dataset-state').textContent=data.state;$('#balance-timestamp').textContent=data.analyzed_at;
    const counts=data.record_types.counts;const cards=[['Total Records',data.summary.total_records,'INFO'],['SFT',counts.sft||0,'INFO'],['Multi-turn',counts.multi_turn||0,'INFO'],['Preference',counts.preference||0,'INFO'],['Balance Status',data.balance_status,data.balance_status],['Warnings',data.warnings.length,data.warnings.length?'WARNING':'CLEAN']];$('#balance-overview').innerHTML=cards.map(([label,value,status])=>`<article class="health-card static-card"><span class="health-card-status ${String(status).toLowerCase()}">${esc(status)}</span><h3>${esc(label)}</h3><strong>${esc(value)}</strong></article>`).join('');
    const typeLabels={sft:'SFT',multi_turn:'Multi-turn',preference:'Preference / DPO',direct_language:'Direct Language',evaluation:'Evaluation',unknown:'Unknown'},turnLabels={'1':'1 turn','2-3':'2–3 turns','4-6':'4–6 turns','7-10':'7–10 turns','11+':'11+ turns'},lengthLabels={very_short:'Very short',short:'Short',medium:'Medium',long:'Long',very_long:'Very long'};
    $('#balance-panels').innerHTML=balanceBars('Record type distribution',data.record_types.distribution.items,typeLabels)+balanceBars('Conversation turns',data.conversation_structure.distribution.items,turnLabels)+balanceBars('Assistant text length',Object.entries(data.length_distribution.assistant.buckets).map(([name,value])=>({name,...value})),lengthLabels)+balanceBars('Source distribution',data.sources.items)+balanceBars('Review type distribution',data.review_types.items,statusArabic)+balanceBars('Error tags',data.error_tags.items,tagArabic)+balanceBars('Language Signal',data.language_signals.items,{arabic_dominant:'Arabic-dominant',english_dominant:'English-dominant',mixed:'Mixed',empty_invalid:'Empty / invalid'})+balanceMetricPanel('Conversation structure',[['Single-turn',data.conversation_structure.single_turn],['Multi-turn',data.conversation_structure.multi_turn],['Mean turns',data.conversation_structure.mean_turns],['Median turns',data.conversation_structure.median_turns],['Minimum',data.conversation_structure.min_turns],['Maximum',data.conversation_structure.max_turns]])+balanceMetricPanel('Length statistics',[['User min / mean / median / max',`${data.length_distribution.user.min} / ${data.length_distribution.user.mean} / ${data.length_distribution.user.median} / ${data.length_distribution.user.max}`],['User p90 / p95',`${data.length_distribution.user.p90} / ${data.length_distribution.user.p95}`],['Assistant min / mean / median / max',`${data.length_distribution.assistant.min} / ${data.length_distribution.assistant.mean} / ${data.length_distribution.assistant.median} / ${data.length_distribution.assistant.max}`],['Assistant p90 / p95',`${data.length_distribution.assistant.p90} / ${data.length_distribution.assistant.p95}`],['Total p90 / p95',`${data.length_distribution.conversation_total.p90} / ${data.length_distribution.conversation_total.p95}`],['Unit','characters']])+balanceMetricPanel('Duplicate & integrity signals',[['Exact records',data.duplicates.exact_records],['Exact user inputs',data.duplicates.exact_user_inputs],['Exact assistant targets',data.duplicates.exact_assistant_targets],['Conversation ID extra',data.duplicates.conversation_id_extra],['Eval conversation overlap',data.duplicates.evaluation_conversation_overlap],['Eval target overlap',data.duplicates.evaluation_target_overlap]]);
    $('#balance-warning-count').textContent=data.warnings.length;$('#balance-warnings').innerHTML=data.warnings.length?data.warnings.map(x=>`<article class="balance-notice ${esc(x.severity)}"><header><span>${esc(x.severity)}</span><code>${esc(x.code)}</code></header><h3>${esc(x.title)}</h3><p>${esc(x.description)}</p><small>${esc(x.dimension)} · observed: ${esc(x.observed)}${x.recommended_min!=null?` · recommended ≥ ${esc(x.recommended_min)}`:''}${x.recommended_max!=null?` · recommended ≤ ${esc(x.recommended_max)}`:''}</small></article>`).join(''):'<div class="success-state">لم تُفعّل قواعد التوازن أي تحذير.</div>';
    $('#balance-recommendations').innerHTML=data.recommendations.map(x=>`<article class="balance-notice recommendation"><header><span>${esc(x.priority)}</span><code>${esc(x.category)}</code></header><h3>${esc(x.reason)}</h3><p>${esc(x.suggested_action)}</p><small>Evidence: ${esc(JSON.stringify(x.evidence))}</small></article>`).join('');
  }catch(error){showBalanceError(error.message);}finally{button.disabled=false;button.textContent=force?'إعادة التحليل':'تحليل التوازن';}
}

async function loadDatasetVersions(){await ensureDatasetVersions();$('#version-list').innerHTML=state.datasetVersions.length?state.datasetVersions.map(x=>`<button data-version-name="${esc(x.version)}"><strong>${esc(x.version)}</strong><span>${x.state}</span><small>${x.created_at?fmtDate(x.created_at):'تاريخ غير موثق'}</small></button>`).join(''):'<div class="empty-inline">لا توجد إصدارات.</div>';const preferred=state.selectedDataset||state.datasetVersions.find(x=>x.version==='gold-v007-balanced')?.version||state.datasetVersions[0]?.version;if(preferred)await showVersionDetail(preferred);}
async function showVersionDetail(version){state.selectedDataset=version;updateLocation('dataset-versions',version,true);const data=await api(`/api/v1/dataset-versions/${encodeURIComponent(version)}`);$$('[data-version-name]').forEach(x=>x.classList.toggle('active',x.dataset.versionName===version));const counts=data.manifest.files||{},provenance=typeof data.provenance==='string'?data.provenance:(data.provenance?.source_version||'Derived version');const canFreeze=data.health.training_readiness.status==='READY'&&data.health.evaluation_integrity.status==='CLEAN';const derived=data.state==='Draft'?`<section class="derived-workflow"><div class="safety-banner">الإصدار الأصلي Frozen ولن يتم تعديله.</div><div class="workflow-actions"><button class="button ghost" data-overlap-analysis="${esc(version)}">فحص Overlaps</button><button class="button primary" data-overlap-plan="${esc(version)}">إنشاء Dry Run</button><button class="button ghost" data-freeze-version="${esc(version)}" ${canFreeze?'':'disabled'}>تجميد الإصدار لاحقًا</button></div><div id="overlap-workflow-result" class="overlap-result"></div></section>`:`<section class="derive-box"><div class="safety-banner">الإصدار الأصلي Frozen ولن يتم تعديله.</div><label>اسم الإصدار المشتق<input id="derived-version-name" dir="ltr" value="${version==='gold-v007-balanced'?'gold-v008-split-clean':esc(version+'-derived')}"></label><button class="button primary" data-derive-version="${esc(version)}">إنشاء إصدار مشتق</button></section>`;$('#version-detail').innerHTML=`<div class="version-hero"><div><span class="eyebrow">${esc(provenance)}</span><h2 dir="ltr">${esc(data.version)}</h2></div><div><button class="button ghost" data-health-version="${esc(version)}">فحص صحة البيانات</button> <span class="frozen-badge ${data.state==='Draft'?'draft':''}">${esc(data.state)}</span></div></div><div class="version-summary"><span>Training Readiness <b>${esc(data.health.training_readiness.status)}</b></span><span>Training <b>${data.health.training_count}</b></span><span>Eval Integrity <b>${esc(data.health.evaluation_integrity.status)}</b></span><span>Leakage <b>${data.eval.conversation_overlap_count}</b></span></div>${derived}<h3>Counts</h3><div class="count-grid">${Object.entries(counts).map(([k,v])=>`<span><code>${esc(k)}</code><b>${v}</b></span>`).join('')}</div><h3>Files & SHA-256</h3><div class="hash-list">${data.files.map(f=>`<div><strong>${esc(f.name)}</strong><span>${f.count==null?'—':f.count} سجل · ${f.bytes} bytes</span><code>${esc(f.sha256)}</code></div>`).join('')}</div><details><summary>Manifest JSON</summary><pre>${esc(JSON.stringify(data.manifest,null,2))}</pre></details>`;}

function overlapTable(data){const items=data.items||[];return `<div class="overlap-summary">${items.length} محادثات متداخلة</div>${items.length?`<div class="overlap-table">${items.map(x=>`<article><code>${esc(x.conversation_id)}</code><div><span>Training: <b>${x.train_records}</b></span><span>Evaluation: <b>${x.eval_records}</b></span><span>Turns: <b>${x.turn_count}</b></span><span>الوجهة: <b>${esc(x.proposed_destination)}</b></span></div><small>${esc(x.source_files.join('، '))}</small><p>${esc(x.reason)}</p></article>`).join('')}</div>`:'<div class="success-state">لا توجد محادثات مشتركة بين التدريب والتقييم.</div>'}`;}
async function deriveVersion(source){const input=$('#derived-version-name'),target=input?.value.trim();if(!target)return toast('أدخل اسم الإصدار المشتق.',true);const button=$(`[data-derive-version="${source}"]`);button.disabled=true;button.textContent='جارٍ الإنشاء...';try{await api(`/api/v1/dataset-versions/${encodeURIComponent(source)}/derive`,{method:'POST',body:JSON.stringify({target_version:target})});state.datasetVersions=[];await loadDatasetVersions();await showVersionDetail(target);toast('تم إنشاء الإصدار المشتق كـ Draft.');}catch(e){toast(e.message,true);}finally{if(button){button.disabled=false;button.textContent='إنشاء إصدار مشتق';}}}
async function analyzeOverlaps(version){const box=$('#overlap-workflow-result');box.innerHTML='<div class="health-state">جارٍ تحليل المحادثات...</div>';try{const data=await api(`/api/v1/dataset-versions/${encodeURIComponent(version)}/conversation-overlaps`);box.innerHTML=overlapTable(data);}catch(e){box.innerHTML=`<div class="error-state">${esc(e.message)}</div>`;}}
async function dryRunOverlaps(version){const box=$('#overlap-workflow-result');box.innerHTML='<div class="health-state">جارٍ إعداد Dry Run...</div>';try{const result=await api(`/api/v1/dataset-versions/${encodeURIComponent(version)}/overlap-plan`,{method:'POST',body:'{}'});state.overlapPlan=result.plan;box.innerHTML=`<div class="success-state">Dry Run فقط — لم تتغير الملفات. سيتم نقل ${result.plan.summary.records_to_move} سجلات.</div>${overlapTable(result.plan)}<button class="button primary apply-plan" data-apply-plan="${esc(version)}">تطبيق الخطة على Draft</button>`;}catch(e){box.innerHTML=`<div class="error-state">${esc(e.message)}</div>`;}}
async function applyOverlapPlan(version){if(!state.overlapPlan)return toast('أنشئ Dry Run حديثًا أولًا.',true);const button=$('[data-apply-plan]');button.disabled=true;button.textContent='جارٍ التطبيق الآمن...';try{await api(`/api/v1/dataset-versions/${encodeURIComponent(version)}/apply-overlap-plan`,{method:'POST',body:JSON.stringify({plan_token:state.overlapPlan.plan_token,dataset_fingerprint:state.overlapPlan.dataset_fingerprint})});state.datasetVersions=[];state.overlapPlan=null;await loadDatasetVersions();await showVersionDetail(version);toast('تم تطبيق الخطة وإعادة حساب manifest وSHA-256.');}catch(e){toast(e.message,true);button.disabled=false;button.textContent='تطبيق الخطة على Draft';}}
async function freezeVersion(version){try{await api(`/api/v1/dataset-versions/${encodeURIComponent(version)}/freeze`,{method:'POST',body:'{}'});state.datasetVersions=[];await loadDatasetVersions();await showVersionDetail(version);toast('تم تجميد الإصدار بعد التحقق من الصحة والبصمات.');}catch(e){toast(e.message,true);}}

async function loadEvalSets(){await ensureDatasetVersions();const version=$('#eval-version').value;if(!version)return;const data=await api(`/api/v1/dataset-versions/${encodeURIComponent(version)}/eval-sets`);$('#eval-status-card').innerHTML=`<div class="eval-lock"><span>🔒</span><div><span class="eyebrow">Locked Holdout</span><h2>${data.leakage_free?'معزول عن التدريب':'تم اكتشاف Leakage'}</h2><p>${data.train_count} training records مقابل ${data.eval_count} evaluation records.</p></div><span class="health-pill ${data.leakage_free?'healthy':'critical'}">${data.leakage_free?'PASS':'FAIL'}</span></div>`;$('#eval-files').innerHTML=data.eval_files.map(x=>`<div class="stat-card"><span>${esc(x.name)}</span><strong>${x.count}</strong></div>`).join('');$('#leakage-detail').innerHTML=`<div class="panel-heading"><h2>Leakage Detection</h2><span class="locked-chip">Locked</span></div><dl class="metric-list"><div><dt>Conversation overlap</dt><dd>${data.conversation_overlap_count}</dd></div><div><dt>Exact target overlap</dt><dd>${data.exact_target_overlap_count}</dd></div></dl>${data.leakage_free?'<div class="success-state">لم يُكتشف تسرب بين ملفات التدريب والتقييم.</div>':`<pre>${esc(JSON.stringify({conversation_overlap:data.conversation_overlap,exact_target_overlap:data.exact_target_overlap},null,2))}</pre>`}`;}

function trainingConfig(){return {method:$('#training-method').value,epochs:Number($('#training-epochs').value),max_steps:Number($('#training-max-steps').value),learning_rate:Number($('#training-lr').value),batch_size:Number($('#training-batch').value),gradient_accumulation_steps:Number($('#training-grad-acc').value),max_seq_length:Number($('#training-seq').value),warmup_ratio:Number($('#training-warmup').value),weight_decay:Number($('#training-weight-decay').value),lr_scheduler:$('#training-scheduler').value,optimizer:$('#training-optimizer').value,lora_rank:Number($('#training-rank').value),lora_alpha:Number($('#training-alpha').value),lora_dropout:Number($('#training-dropout').value),packing:$('#training-packing').checked,gradient_checkpointing:$('#training-checkpointing').checked,bf16:$('#training-bf16').checked,fp16:$('#training-fp16').checked};}
function trainingPayload(){return {dataset_version:$('#training-dataset').value,model_id:$('#training-model').value,training_config:trainingConfig(),runtime_target:{type:'wsl',distro:'NajdiTrain'}};}
function gateHtml(gate){const issues=gate.blocking_issues||[],warnings=gate.warnings||[];return `<div class="panel-heading"><h2>بوابة جودة البيانات</h2><span class="gate-badge ${String(gate.status).toLowerCase()}">${esc(uiStatus(gate.status))}</span></div><div class="quality-summary"><span>إصدار البيانات <b dir="ltr">${esc(gate.dataset)}</b></span><span>سجلات التدريب <b>${gate.dataset_counts?.training??'—'}</b></span><span>العوائق <b>${issues.length}</b></span><span>التحذيرات <b>${warnings.length}</b></span></div>${issues.map(x=>`<div class="gate-message blocked"><code>${esc(x.code)}</code><span>${esc(x.message)}</span></div>`).join('')}${warnings.map(x=>`<div class="gate-message warning"><code>${esc(x.code)}</code><span>${esc(x.message)}</span></div>`).join('')}<small class="fingerprint technical-value" dir="ltr">${esc(gate.dataset_fingerprint||'لا توجد بصمة')}</small>`;}
function planHtml(preflight){const p=preflight.training_plan,v=preflight.vram_estimate,m=preflight.model;if(!p)return '<div class="error-state">بوابة الجودة تمنع حساب خطة قابلة للاستخدام.</div>';return `<div class="panel-heading"><h2>خطة التدريب</h2><span class="gate-badge pass">مُعدّة</span></div><dl class="metric-list"><div><dt>النموذج</dt><dd>${esc(m.display_name)}</dd></div><div><dt>الطريقة</dt><dd>${esc(preflight.training_config.method)}</dd></div><div><dt>سجلات التدريب</dt><dd>${p.training_records}</dd></div><div><dt>حجم الدفعة الفعلي</dt><dd>${p.effective_batch_size}</dd></div><div><dt>الدفعات لكل دورة</dt><dd>${p.batches_per_epoch}</dd></div><div><dt>خطوات المحسّن لكل دورة</dt><dd>${p.optimizer_steps_per_epoch}</dd></div><div><dt>إجمالي خطوات المحسّن</dt><dd>${p.estimated_total_optimizer_steps}</dd></div><div><dt>نقاط الحفظ المتوقعة</dt><dd>${p.estimated_checkpoint_count}</dd></div><div><dt>تقدير VRAM</dt><dd>${esc(uiStatus(v.status))}${v.estimated_requirement_gb?` · ${v.estimated_requirement_gb} GB`:''}</dd></div></dl><div class="estimate-note">ثقة التقدير: ${esc(uiStatus(v.confidence))} — هذا تقدير وليس ضمانًا، ويلزم فحص بيئة التشغيل.</div>`;}
async function loadTrainingSetup(){const [datasets,models]=await Promise.all([api('/api/v1/training/datasets'),api('/api/v1/training/models')]);$('#training-dataset').innerHTML=datasets.items.map(x=>`<option value="${esc(x.version)}" ${!x.readable?'disabled':''}>${esc(x.version)} — ${esc(x.state)}</option>`).join('');if(datasets.items.some(x=>x.version==='gold-v008-split-clean'))$('#training-dataset').value='gold-v008-split-clean';$('#training-model').innerHTML=models.items.map(x=>`<option value="${esc(x.id)}" ${!x.enabled?'disabled':''}>${esc(x.display_name)}</option>`).join('');state.trainingPreflight=null;await runTrainingPreflight();}
async function runTrainingPreflight(){const button=$('#run-training-preflight');button.disabled=true;button.textContent='جارٍ الفحص…';try{const data=await api('/api/v1/training/preflight',{method:'POST',body:JSON.stringify(trainingPayload())});state.trainingPreflight=data;const gate=data.dataset;$('#quality-gate-badge').textContent=uiStatus(gate.status);$('#quality-gate-badge').className=`gate-badge ${String(gate.status).toLowerCase()}`;$('#quality-gate-result').innerHTML=gateHtml(gate);$('#training-plan-result').innerHTML=planHtml(data);$('#create-training-job').disabled=!data.can_create_draft;}catch(e){state.trainingPreflight=null;$('#quality-gate-result').innerHTML=`<div class="error-state">${esc(e.message)}</div>`;$('#create-training-job').disabled=true;}finally{button.disabled=false;button.textContent='تشغيل فحص الجاهزية';}}
function runtimeResultHtml(data){const failed=(data.checks||[]).filter(x=>x.status!=='PASS');const gpu=data.detected?.gpu;return `<div class="panel-heading"><h2>Runtime Check</h2><span class="gate-badge ${data.status.startsWith('AVAILABLE')?'pass':'unavailable'}">${esc(data.status)}</span></div><dl class="metric-list"><div><dt>WSL distros</dt><dd>${esc((data.detected?.wsl_distros||[]).map(x=>`${x.name} (${x.state})`).join('، ')||'—')}</dd></div><div><dt>Python</dt><dd>${esc(data.detected?.python||'—')}</dd></div><div><dt>GPU</dt><dd>${esc(gpu?.name||'—')}</dd></div><div><dt>VRAM free / total</dt><dd>${gpu?`${Math.round(gpu.free_vram_mb)} / ${Math.round(gpu.total_vram_mb)} MiB`:'—'}</dd></div><div><dt>CUDA</dt><dd>${data.detected?.cuda_available?'PASS':'UNAVAILABLE'}</dd></div><div><dt>Unsloth</dt><dd>${esc(data.detected?.packages?.unsloth?.version||'UNAVAILABLE')}</dd></div></dl>${failed.map(x=>`<div class="gate-message ${x.status==='FAIL'?'error':'warning'}"><code>${esc(x.code||x.name)}</code><span>${esc(x.details||String(x.value??''))}</span></div>`).join('')}<small>Checked: ${fmtDate(data.checked_at)} · freshness ${data.max_age_seconds}s</small>`;}
async function checkTrainingRuntime(){const button=$('#check-training-runtime');button.disabled=true;button.textContent='جارٍ الفحص…';try{const data=await api('/api/v1/training/runtime-check',{method:'POST',body:JSON.stringify({runtime_id:'najditrain-wsl'})});$('#runtime-result').innerHTML=runtimeResultHtml(data);}catch(e){$('#runtime-result').innerHTML=`<div class="error-state">${esc(e.message)}</div>`;}finally{button.disabled=false;button.textContent='فحص بيئة التشغيل';}}
async function registerModelCandidate(form){const button=form.querySelector('button[type="submit"]'),status=$('#model-register-status');button.disabled=true;status.textContent='جارٍ تسجيل المرشح…';try{const values=Object.fromEntries(new FormData(form));if(values.model_size_gb)values.model_size_gb=Number(values.model_size_gb);else delete values.model_size_gb;const result=await api('/api/v1/training/models',{method:'POST',body:JSON.stringify(values)});status.className='detail-status success-state';status.textContent=`تم تسجيل ${result.model.display_name}. يلزم التحقق قبل التدريب.`;form.reset();await loadTrainingSetup();$('#training-model').value=result.model.id;await runTrainingPreflight();}catch(e){status.className='detail-status error-state';status.textContent=e.message;}finally{button.disabled=false;}}
async function createTrainingJob(){const button=$('#create-training-job');button.disabled=true;button.textContent='جارٍ الحفظ...';try{const result=await api('/api/v1/training/jobs',{method:'POST',body:JSON.stringify(trainingPayload())});state.selectedTrainingJob=result.job.job_id;toast(`تم إنشاء ${result.job.job_id} كـ DRAFT.`);switchView('training-jobs');}catch(e){toast(e.message,true);button.disabled=false;button.textContent='إنشاء مهمة تدريب';}}
async function loadTrainingJobs(){const data=await api('/api/v1/training/jobs');state.trainingJobs=data.items;$('#training-job-list').innerHTML=data.items.length?data.items.map(j=>`<button data-training-job="${esc(j.job_id)}" aria-label="${esc(j.job_id)}، ${esc(uiStatus(j.status))}"><strong dir="ltr">${esc(j.job_id)}</strong><span class="job-status ${String(j.status).toLowerCase()}">${esc(uiStatus(j.status))}</span><small><bdi>${esc(j.dataset_version)}</bdi> · ${fmtDate(j.updated_at)}</small></button>`).join(''):'<div class="empty-inline">لا توجد مهام تدريب بعد.</div>';const id=state.selectedTrainingJob||data.items[0]?.job_id;if(id)await showTrainingJob(id);}
function executionGateHtml(g){const detected=g.checks?.runtime?.detected||{},worker=g.checks?.worker||{},vram=g.checks?.vram||{},staging=g.checks?.staging||{};return `<section class="execution-readiness"><div class="panel-heading"><h3>جاهزية التنفيذ</h3><span class="gate-badge ${String(g.status).toLowerCase()}">${esc(uiStatus(g.status))}</span></div><div class="readiness-grid"><span>البيانات<b>${esc(uiStatus(g.checks?.dataset_gate))}</b></span><span>التجهيز<b>${esc(uiStatus(staging.status))}</b></span><span>النموذج<b>${g.blockers.some(x=>x.code.startsWith('MODEL'))?'محظور':'ناجح'}</b></span><span>بيئة التشغيل<b>${esc(uiStatus(g.checks?.runtime?.status))}</b></span><span>GPU<b>${esc(detected.gpu?.name||'—')}</b></span><span>CUDA<b>${detected.cuda_available?'ناجح':'—'}</b></span><span>Unsloth<b>${esc(detected.packages?.unsloth?.version||'—')}</b></span><span>العامل<b>${esc(uiStatus(worker.state))} · ${esc(uiStatus(worker.heartbeat_freshness))}</b></span><span>VRAM<b>${esc(uiStatus(vram.status))}</b></span></div>${g.blockers.map(x=>`<div class="gate-message error"><code>${esc(x.code)}</code><span>${esc(x.message)}</span></div>`).join('')}${g.warnings.map(x=>`<div class="gate-message warning"><code>${esc(x.code)}</code><span>${esc(x.message)}</span></div>`).join('')}<div class="training-actions"><button class="button ghost" data-job-stage>تجهيز البيانات</button><button class="button ghost" data-job-adapter>نشر Adapter</button><button class="button ghost" data-job-runtime>فحص بيئة التشغيل</button><button class="button ghost" data-job-worker>تشغيل العامل</button><button class="button ghost" data-job-gate>تحديث بوابة التنفيذ</button><button class="button primary" data-job-dry-run>تنفيذ محاكاة آمنة</button><button class="button primary" data-job-smoke ${g.status.startsWith('PASS')?'':'disabled'}>اختبار دخاني (خطوتان)</button></div><div id="job-dry-run-result"></div><div id="job-attempt-monitor"></div></section>`;}
async function showTrainingJob(jobId){const [j,g]=await Promise.all([api(`/api/v1/training/jobs/${encodeURIComponent(jobId)}`),api(`/api/v1/training/jobs/${encodeURIComponent(jobId)}/execution-gate`)]);let attempt=null;if(j.latest_attempt_id){try{attempt=await api(`/api/v1/training/jobs/${encodeURIComponent(jobId)}/attempts/${encodeURIComponent(j.latest_attempt_id)}`);}catch{attempt=null;}}state.selectedTrainingJob=jobId;state.executionGate=g;$$('[data-training-job]').forEach(x=>x.classList.toggle('active',x.dataset.trainingJob===jobId));const ready=j.status==='DRAFT'?`<label class="warning-ack"><input id="job-warning-ack" type="checkbox"> اطلعت على التحذيرات.</label><button class="button primary" data-job-ready="${esc(jobId)}">تحويل إلى READY</button>`:'';const cancel=['DRAFT','READY'].includes(j.status)?`<button class="button ghost" data-job-cancel="${esc(jobId)}">إلغاء المهمة</button>`:'';const ar=attempt?.result?.adapter_result,isFull=attempt?.attempt_type==='FULL',attemptHtml=attempt?`<section class="execution-readiness"><div class="panel-heading"><h3>${isFull?'Full Training':'Smoke'} Result</h3><span class="gate-badge ${attempt.status==='COMPLETED'?'pass':'unavailable'}">${esc(attempt.status)}</span></div><div class="readiness-grid"><span>Attempt<b>${esc(attempt.attempt_id)}</b></span><span>Steps<b>${ar?.global_step??attempt.result?.metric_count??0} / ${attempt.expected_steps??2}</b></span><span>First loss<b>${ar?.first_loss??ar?.losses?.[0]??'—'}</b></span><span>Last loss<b>${ar?.last_loss??ar?.losses?.at(-1)??'—'}</b></span><span>NaN / Inf<b>${ar?.nan_or_inf?'FAIL':'NONE'}</b></span><span>Exit code<b>${attempt.exit_code??'—'}</b></span></div></section>`:'';const fullHtml=j.production_mode?`<section class="execution-readiness"><div class="panel-heading"><h3>Full Training Authorization</h3><span class="gate-badge ${j.full_training_status==='PASSED'?'pass':'unavailable'}">${esc(j.full_training_status||'LOCKED')}</span></div><p>التصريح server-side، مدته 5 دقائق، أحادي الاستخدام ومرتبط بكل البصمات.</p><div class="training-actions"><button class="button ghost" data-full-dry-run>Full Dry Run</button><button class="button ghost" data-full-authorize>طلب تصريح</button><button class="button primary" data-full-start ${state.fullAuthToken?'':'disabled'}>بدء التدريب الكامل</button></div><label class="wide-label">الإقرار المطلوب<input id="full-training-ack" dir="auto" value="أوافق على بدء Full Training للمهمة ${esc(j.job_id)}"></label><div id="full-training-result"></div></section>`:'';$('#training-job-detail').innerHTML=`<div class="version-hero"><div><span class="eyebrow">Training Job</span><h2 dir="ltr">${esc(j.job_id)}</h2></div><span class="job-status ${j.status.toLowerCase()}">${esc(j.status)}</span></div><div class="version-summary"><span>Dataset<b>${esc(j.dataset_version)}</b></span><span>Method<b>${esc(j.training_config.method)}</b></span><span>Full<b>${esc(j.full_training_status||'NOT RUN')}</b></span><span>Runtime<b>${esc(j.runtime_target?.runtime_id||j.runtime_target?.distro||'—')}</b></span></div><dl class="metric-list"><div><dt>Model</dt><dd>${esc(j.model_config.display_name)}</dd></div><div><dt>Fingerprint</dt><dd class="technical-value">${esc(j.dataset_fingerprint)}</dd></div><div><dt>Plan</dt><dd>${j.calculated_steps?.estimated_total_optimizer_steps??'—'} steps · ${j.training_config.epochs} epochs</dd></div></dl>${executionGateHtml(g)}${fullHtml}${attemptHtml}<div class="training-actions">${ready}${cancel}</div>`;}
async function checkJobRuntime(){const button=$('[data-job-runtime]');button.disabled=true;try{await api('/api/v1/training/runtime-check',{method:'POST',body:JSON.stringify({runtime_id:'najditrain-wsl'})});await showTrainingJob(state.selectedTrainingJob);toast('اكتمل Runtime Check الآمن دون تشغيل تدريب.');}catch(e){toast(e.message,true);button.disabled=false;}}
async function runJobDryRun(){const button=$('[data-job-dry-run]');button.disabled=true;button.textContent='جارٍ Dry Run...';try{const data=await api(`/api/v1/training/jobs/${encodeURIComponent(state.selectedTrainingJob)}/dry-run`,{method:'POST',body:'{}'});$('#job-dry-run-result').innerHTML=`<div class="dry-run-result"><strong>Dry Run: ${esc(data.status)}</strong><p>${data.training_started?'Unexpected execution':'لم يبدأ التدريب.'}</p><pre dir="ltr">${esc(data.command.preview)}</pre>${data.execution_manifest?`<small>${esc(data.execution_manifest)}</small>`:''}</div>`;toast(`Dry Run: ${data.status}`);}catch(e){toast(e.message,true);button.disabled=false;button.textContent='تنفيذ Dry Run';}}
async function stageJobDataset(){const job=await api(`/api/v1/training/jobs/${encodeURIComponent(state.selectedTrainingJob)}`);await api('/api/v1/training/runtimes/najditrain-wsl/stage',{method:'POST',body:JSON.stringify({version:job.dataset_version})});await showTrainingJob(job.job_id);toast('تم تجهيز نسخة مطابقة بالـchecksums.');}
async function deployJobAdapter(){await api('/api/v1/training/runtimes/najditrain-wsl/deploy-adapter',{method:'POST',body:'{}'});toast('تم نشر Adapter المقيد للـSmoke.');}
async function startJobWorker(){await api('/api/v1/training/runtimes/najditrain-wsl/worker/start',{method:'POST',body:'{}'});await showTrainingJob(state.selectedTrainingJob);toast('Worker جاهز في وضع IDLE.');}
async function monitorAttempt(jobId,attemptId){let done=false;while(!done&&state.selectedTrainingJob===jobId){const attempt=await api(`/api/v1/training/jobs/${encodeURIComponent(jobId)}/attempts/${encodeURIComponent(attemptId)}`);const logs=await api(`/api/v1/training/jobs/${encodeURIComponent(jobId)}/attempts/${encodeURIComponent(attemptId)}/logs?stream=stdout&offset=0`);const box=$('#job-attempt-monitor');if(box)box.innerHTML=`<div class="dry-run-result"><strong>Smoke ${esc(attempt.status)} · max_steps=2</strong><pre dir="ltr">${esc(logs.text||'بانتظار السجل...')}</pre></div>`;done=['COMPLETED','FAILED','CANCELLED','INTERRUPTED'].includes(attempt.status);if(!done)await new Promise(resolve=>setTimeout(resolve,3000));}if(done)await showTrainingJob(jobId);}
async function startSmokeJob(){const gate=state.executionGate;if(!gate||!gate.status.startsWith('PASS'))return toast('Execution Gate غير ناجح.',true);if(!window.confirm('سيبدأ Smoke Test فعليًا فقط: خطوتان optimizer، بلا Full Training. هل تريد المتابعة؟'))return;const result=await api(`/api/v1/training/jobs/${encodeURIComponent(state.selectedTrainingJob)}/smoke`,{method:'POST',body:JSON.stringify({confirm_smoke_only:true,max_steps:2})});toast('بدأ Smoke Test المقيد بخطوتين.');monitorAttempt(state.selectedTrainingJob,result.attempt.attempt_id).catch(e=>toast(e.message,true));}
async function runFullDryRun(){const data=await api(`/api/v1/training/jobs/${encodeURIComponent(state.selectedTrainingJob)}/full-dry-run`,{method:'POST',body:'{}'});$('#full-training-result').innerHTML=`<div class="dry-run-result">Full Dry Run: ${esc(data.status)}<pre dir="ltr">${esc(data.command.preview)}</pre></div>`;}
async function authorizeFull(){const acknowledgement=$('#full-training-ack').value;const data=await api(`/api/v1/training/jobs/${encodeURIComponent(state.selectedTrainingJob)}/authorize-full-training`,{method:'POST',body:JSON.stringify({acknowledgement})});state.fullAuthToken=data.token;state.fullAuthJob=state.selectedTrainingJob;$('#full-training-result').innerHTML=`<div class="success-state">تصريح أحادي الاستخدام صالح حتى ${esc(data.expires_at)}.</div>`;$('[data-full-start]').disabled=false;}
async function startFull(){if(state.fullAuthJob!==state.selectedTrainingJob||!state.fullAuthToken)throw new Error('لا يوجد تصريح صالح لهذه المهمة.');const token=state.fullAuthToken;state.fullAuthToken=null;const data=await api(`/api/v1/training/jobs/${encodeURIComponent(state.selectedTrainingJob)}/start-full-training`,{method:'POST',body:JSON.stringify({authorization_token:token})});monitorAttempt(state.selectedTrainingJob,data.attempt.attempt_id).catch(e=>toast(e.message,true));}
async function markTrainingJobReady(id){try{await api(`/api/v1/training/jobs/${encodeURIComponent(id)}/ready`,{method:'POST',body:JSON.stringify({acknowledge_warnings:$('#job-warning-ack')?.checked||false})});await loadTrainingJobs();toast('أصبحت المهمة READY. لم يبدأ التدريب.');}catch(e){toast(e.message,true);}}
async function cancelTrainingJob(id){try{await api(`/api/v1/training/jobs/${encodeURIComponent(id)}/cancel`,{method:'POST',body:'{}'});await loadTrainingJobs();toast('تم إلغاء المهمة دون تشغيل تدريب.');}catch(e){toast(e.message,true);}}

async function loadDashboard(){
  const [analyticsData,exportsData,datasetData,platform]=await Promise.all([api('/api/v1/analytics'),api('/api/v1/exports'),api('/api/v1/training-dataset'),api('/api/v1/platform/status')]);
  const s=analyticsData.summary;
  const eligible=(datasetData.reviews?.length||0)+(datasetData.manual_sft?.length||0)+(datasetData.direct_language?.length||0)+(datasetData.preference_pairs?.length||0);
  const stats=[['محادثات',s.total_conversations],['بانتظار المراجعة',s.pending_reviews],['مؤهل للبناء',eligible],['إصدارات Gold',exportsData.items.length]];
  $('#dashboard-stats').innerHTML=stats.map(([label,value])=>`<div class="stat-card"><span>${label}</span><strong>${value??0}</strong></div>`).join('');
  $('#dashboard-exports').innerHTML=exportsData.items.length?exportsData.items.slice(0,4).map(item=>`<div class="export-row"><strong>${esc(item.version)}</strong><span>${fmtDate(item.created_at)}</span><span>${item.record_count} سجل</span></div>`).join(''):'<div class="empty-inline compact-empty">لا توجد نسخة Gold بعد.</div>';
  const p3=platform.phase3||{},p4=platform.phase4||{};
  const known=p3.decision!=='UNKNOWN'&&p4.status!=='UNKNOWN';
  $('#dashboard-readiness').innerHTML=`<li><span class="status-dot ${known?'ok':'neutral'}"></span>Phase 3: <b>${esc(p3.decision||'UNKNOWN')}</b> · ${p3.reviewed??'—'}/${p3.total??'—'} مراجعة</li><li><span class="status-dot ${p4.status==='BLOCKED'?'neutral':'ok'}"></span>Phase 4: <b>${esc(p4.status||'UNKNOWN')}</b> — ${esc(p4.reason||'UNVERIFIED')}</li>${(platform.warnings||[]).map(w=>`<li><span class="status-dot neutral"></span>${esc(w)}</li>`).join('')}`;
}

async function loadConfig() {
  const config = await api('/api/v1/config'); state.tags = config.error_tags;
  $('#error-tags').innerHTML = state.tags.map(tag=>`<button type="button" data-tag="${esc(tag)}">${esc(tagArabic[tag]||tag)}</button>`).join('');
  $('#filter-tag').innerHTML += state.tags.map(tag=>`<option value="${esc(tag)}">${esc(tagArabic[tag]||tag)}</option>`).join('');
  $('#error-tags').addEventListener('click', event=>{const button=event.target.closest('button');if(button)button.classList.toggle('selected');});
}

async function loadQueue() {
  const data = await api('/api/v1/review-queue?include_demo=1');
  state.queue = data.items; state.queueIndex = Math.min(state.queueIndex, Math.max(0,state.queue.length-1));
  $('#nav-pending').textContent = state.queue.length;
  $('#queue-empty').classList.toggle('hidden', state.queue.length>0); $('#review-workspace').classList.toggle('hidden', !state.queue.length);
  if (state.queue.length) renderReview();
}

function renderReview() {
  const item = state.queue[state.queueIndex]; state.reviewStatus = null; state.reviewActionPending = false;
  $('#review-conversation-title').textContent = item.conversation_title || item.external_conversation_id;
  $('#review-demo').classList.toggle('hidden', !item.demo);
  $('#review-meta').innerHTML = [item.model_name||'مودل غير محدد',item.provider||'مزود غير محدد',item.channel,fmtDate(item.message_created_at)].map(x=>`<span>${esc(x)}</span>`).join('');
  $('#context-messages').innerHTML = item.context.map(message=>`<article class="message ${esc(message.role)} ${message.id===item.message_id?'active-message':''}"><span class="role">${message.role==='user'?'المستخدم':message.role==='assistant'?'المساعد':esc(message.role)}</span><p>${esc(message.content)}</p>${message.id===item.message_id?'<span class="message-status">الرد الجاري مراجعته</span>':''}</article>`).join('');
  $('#original-response').textContent = item.original_response; $('#corrected-response').value = item.corrected_response||item.original_response; $('#review-notes').value=item.review_notes||''; $('#ignored-reason').value=''; $('#reviewer-identity').value=item.reviewer||'human';
  $$('.status-grid button').forEach(button=>button.classList.remove('selected')); $('#edit-review-panel').classList.add('hidden'); $('#correction-editor').classList.add('hidden'); $('#correction-save-row').classList.add('hidden'); $('#save-review').disabled=true;
  $$('#error-tags button').forEach(button=>button.classList.remove('selected')); $$('.check-grid input').forEach(input=>input.checked=false); $('#training-eligible').checked=true;
  $$('.review-actions button').forEach(button=>button.disabled=false); $('#confirm-review-delete').disabled=false;
  $('#queue-position').textContent = `${state.queueIndex+1} من ${state.queue.length}`; $('#queue-progress').style.width = `${((state.queueIndex+1)/state.queue.length)*100}%`;
}

function selectReviewStatus(status) {
  if (state.reviewActionPending) return;
  state.reviewStatus = status;
  $$('.status-grid button').forEach(button=>button.classList.toggle('selected',button.dataset.status===status));
  $('#correction-editor').classList.remove('hidden');
  $('#corrected-response').focus(); $('#corrected-response').select();
  $('#save-review').disabled=false;
}

function reviewPayload() {
  return {review_notes:$('#review-notes').value,reviewer:$('#reviewer-identity').value,expected_updated_at:state.queue[state.queueIndex]?.updated_at,training_eligible:$('#training-eligible').checked,evaluation_only:$('#evaluation-only').checked,exclude_from_training:$('#exclude-training').checked,needs_fact_check:$('#needs-fact-check').checked,contains_personal_data:$('#contains-personal').checked,contains_sensitive_data:$('#contains-sensitive').checked,tags:$$('#error-tags button.selected').map(b=>b.dataset.tag)};
}

function setReviewBusy(busy) {
  state.reviewActionPending=busy;
  $$('.review-actions button').forEach(button=>button.disabled=busy);
  $('#save-review').disabled=busy||!state.reviewStatus;
  $('#confirm-review-delete').disabled=busy;
}

function finishReviewAction(reviewId,message) {
  const index=state.queue.findIndex(item=>Number(item.id)===Number(reviewId));
  if(index>=0)state.queue.splice(index,1);
  if(state.queueIndex>=state.queue.length)state.queueIndex=Math.max(0,state.queue.length-1);
  $('#nav-pending').textContent=state.queue.length;toast(message);
  if(state.queue.length)renderReview();else{$('#queue-empty').classList.remove('hidden');$('#review-workspace').classList.add('hidden');}
}

async function runReviewAction(action,payload,message) {
  if(state.reviewActionPending||!state.queue.length)return;
  const item=state.queue[state.queueIndex];setReviewBusy(true);
  try{await api(`/api/v1/reviews/${item.id}/${action}`,{method:'POST',body:JSON.stringify(payload)});finishReviewAction(item.id,message);}
  catch(error){toast(error.message||'تعذر تنفيذ الإجراء. حاول مرة أخرى.',true);setReviewBusy(false);}
}

async function approveReview(){return runReviewAction('approve',reviewPayload(),'تم اعتماد العينة والانتقال للتالية.');}
async function excludeReview(){const reason=$('#ignored-reason').value.trim();if(!reason){toast('اكتب سبب الاستبعاد أولًا.',true);return;}return runReviewAction('exclude',{...reviewPayload(),reason},'تم استبعاد العينة مع حفظ أصلها وبيانات المراجع.');}

function openEditReview() {
  if(state.reviewActionPending)return;
  state.reviewStatus=null;$('#edit-review-panel').classList.remove('hidden');$('#correction-save-row').classList.remove('hidden');$('#correction-editor').classList.add('hidden');$('#save-review').disabled=true;
  $$('.status-grid button').forEach(button=>button.classList.remove('selected'));
}

function cancelEditReview() {
  state.reviewStatus=null;$('#edit-review-panel').classList.add('hidden');$('#correction-save-row').classList.add('hidden');$('#correction-editor').classList.add('hidden');
}

async function saveReview() {
  if (!state.reviewStatus||state.reviewActionPending) return;
  const payload={...reviewPayload(),review_status:state.reviewStatus,corrected_response:$('#corrected-response').value};
  const button=$('#save-review');button.textContent='جارٍ الحفظ…';
  try{await runReviewAction('correct',payload,'تم حفظ التصحيح والانتقال للتالية.');}
  finally{button.textContent='حفظ التعديل والانتقال';}
}

function openDeleteReview(){if(!state.reviewActionPending&&state.queue.length)$('#review-delete-dialog').showModal();}
async function confirmDeleteReview(){
  if(state.reviewActionPending)return;
  const currentId=state.queue[state.queueIndex]?.id;
  await runReviewAction('delete',{},'تم نقل العينة إلى المحذوفات.');
  if(!state.queue.some(item=>Number(item.id)===Number(currentId)))$('#review-delete-dialog').close();
}

async function loadConversations() {
  const search=encodeURIComponent($('#conversation-search').value||'');const channel=encodeURIComponent($('#conversation-channel').value||'');
  const data=await api(`/api/v1/conversations?search=${search}&channel=${channel}`);
  data.items.forEach(item=>state.channels.add(item.channel));populateChannelFilters();
  $('#conversation-list').innerHTML=data.items.length?data.items.map(item=>`<button class="conversation-item" data-id="${item.id}"><small>${item.message_count} رسائل</small><strong>${esc(item.title||item.external_conversation_id)}</strong><span>${esc(item.model_name||'غير محدد')} · ${esc(item.channel)} · ${item.pending_count||0} معلّق</span></button>`).join(''):'<div class="empty-inline">لا توجد نتائج.</div>';
}

function populateChannelFilters(){['#conversation-channel','#filter-channel'].forEach(selector=>{const select=$(selector),current=select.value,first=select.options[0].outerHTML;select.innerHTML=first+[...state.channels].sort().map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');select.value=current;});}

async function showConversation(id) {
  const data=await api(`/api/v1/conversations/${id}`);$$('.conversation-item').forEach(b=>b.classList.toggle('active',Number(b.dataset.id)===Number(id)));
  $('#conversation-detail').innerHTML=`<header class="conversation-header"><h2>${esc(data.conversation.title)}</h2><p>${esc(data.conversation.external_conversation_id)}</p><div class="meta-row"><span>${esc(data.conversation.model_name||'غير محدد')}</span><span>${esc(data.conversation.provider||'غير محدد')}</span><span>${esc(data.conversation.channel)}</span>${data.conversation.demo?'<span class="badge demo">تجريبي</span>':''}</div></header><div class="chat-stream">${data.messages.map(message=>`<article class="message ${esc(message.role)}"><span class="role">${message.role==='user'?'المستخدم':message.role==='assistant'?'المساعد':esc(message.role)} ${message.review_status?`· <span class="status-badge status-${esc(message.review_status)}">${esc(statusArabic[message.review_status])}</span>`:''}</span><p>${esc(message.content)}</p>${message.corrected_response?`<div class="answer corrected"><strong>التصحيح:</strong><br>${esc(message.corrected_response)}</div>`:''}</article>`).join('')}</div>`;
}

async function loadReviewed(){
  const params=new URLSearchParams({search:$('#reviewed-search').value,status:'',review_status:$('#filter-status').value,channel:$('#filter-channel').value,tag:$('#filter-tag').value,training_eligible:$('#filter-eligible').value,date_from:$('#filter-date-from').value,date_to:$('#filter-date-to').value});
  const data=await api(`/api/v1/reviewed?${params}`);data.items.forEach(i=>state.channels.add(i.channel));populateChannelFilters();
  state.reviewedSelected.clear();updateReviewedBulk();
  $('#reviewed-list').innerHTML=data.items.length?data.items.map(item=>`<article class="reviewed-card"><header><label class="inline-check"><input class="reviewed-row-check" type="checkbox" data-review-id="${item.id}"> تحديد</label><h3>${esc(item.conversation_title)}</h3><span class="status-badge status-${esc(item.review_status)}">${esc(statusArabic[item.review_status])}</span></header><div class="answer"><strong>الأصل:</strong> ${esc(compact(item.original_response,220))}</div>${item.corrected_response?`<div class="answer corrected"><strong>التصحيح المحفوظ:</strong> ${esc(compact(item.corrected_response,220))}</div>`:''}<div class="tag-picker">${item.tags.map(tag=>`<span class="status-badge status-FULL_CORRECTION">${esc(tagArabic[tag]||tag)}</span>`).join('')}</div><footer><span>${esc(item.reviewer||'—')} · ${fmtDate(item.updated_at)} · ${esc(item.model_name||'—')} · ${esc(item.channel)}</span><span>${item.training_eligible?'مؤهل':'غير مؤهل'}${item.evaluation_only?' · تقييم':''}</span></footer>${['IGNORED','DELETED'].includes(item.review_status)?`<button class="button ghost" data-restore-review="${item.id}">استعادة للمراجعة</button>`:`<button class="button ignore-action" data-exclude-review="${item.id}">استبعاد</button>`}</article>`).join(''):'<div class="empty-state"><h2>لا توجد نتائج</h2><p>غيّر الفلاتر أو ابدأ بمراجعة الردود.</p></div>';
}

function updateReviewedBulk(){const count=state.reviewedSelected.size;$('#bulk-review-count').textContent=count?`${count} مراجعات محددة`:'لم تُحدد مراجعات';$('#bulk-exclude-reviews').disabled=!count;$('#bulk-restore-reviews').disabled=!count;}
async function bulkReviewed(action,ids=[...state.reviewedSelected]){const reason=$('#bulk-review-reason').value.trim();if(!reason){toast('سبب الاستبعاد أو الاستعادة مطلوب.',true);return;}const result=await api('/api/v1/reviews/bulk',{method:'POST',body:JSON.stringify({action,review_ids:ids,reason,reviewer:'human'})});toast(`اكتملت العملية الذرية على ${result.count} مراجعات.`);await loadReviewed();await loadQueue();}

function addSftTurn(role='user',content=''){
  const row=document.createElement('div');row.className='turn-row';row.innerHTML=`<select class="turn-role"><option value="user" ${role==='user'?'selected':''}>User</option><option value="assistant" ${role==='assistant'?'selected':''}>Assistant</option><option value="system" ${role==='system'?'selected':''}>System</option></select><textarea class="turn-content" placeholder="اكتب محتوى الدور…">${esc(content)}</textarea><button type="button" aria-label="حذف الدور">×</button>`;row.querySelector('button').addEventListener('click',()=>row.remove());$('#sft-turns').append(row);
}

function formPayload(form){const raw=Object.fromEntries(new FormData(form));$$('input[type=checkbox]',form).forEach(input=>raw[input.name]=input.checked);return raw;}
async function submitDataForm(form,endpoint,extra={}){const button=form.querySelector('button[type=submit]');button.disabled=true;try{await api(endpoint,{method:'POST',body:JSON.stringify({...formPayload(form),...extra})});toast('تم حفظ السجل مع معلومات المصدر.');form.reset();}catch(error){toast(error.message,true);}finally{button.disabled=false;}}

const manualTypeLabels={sft:'محادثة / SFT',direct:'نص لغوي مباشر',dpo:'زوج تفضيل / DPO'};
const languageLabels={najdi_riyadh:'نجدي / الرياض',saudi_neutral:'سعودي محايد',msa:'MSA',technical_arabic:'Technical Arabic',formal_arabic:'Formal Arabic'};

function manualParams(){
  return new URLSearchParams({
    search:$('#manual-search').value,type:$('#manual-type').value,status:$('#manual-status').value,
    language_layer:$('#manual-language').value,source:$('#manual-source').value,origin:$('#manual-origin').value,
    domain:$('#manual-domain').value,date_from:$('#manual-date-from').value,date_to:$('#manual-date-to').value,
    sort:$('#manual-sort').value,show_archived:$('#manual-show-archived').checked?'1':'0'
  });
}

async function loadManualData(){
  const data=await api(`/api/v1/manual-data?${manualParams()}`);state.manualItems=data.items;state.manualSelected.clear();updateManualBulk();
  const labels=[['total','إجمالي العناصر'],['sft','SFT'],['direct','نص لغوي مباشر'],['dpo','DPO'],['eligible','مؤهل للتدريب'],['ineligible','غير مؤهل'],['archived','مؤرشف'],['excluded','مستبعد من التدريب'],['ignored','تم تجاهلها'],['deleted','محذوفة']];
  $('#manual-stats').innerHTML=labels.map(([key,label])=>`<div class="stat-card"><span>${label}</span><strong>${data.summary[key]||0}</strong></div>`).join('');
  for(const key of ['source','origin','domain'])$(`#manual-${key}-options`).innerHTML=(data.facets[key]||[]).map(x=>`<option value="${esc(x)}"></option>`).join('');
  $('#manual-list').innerHTML=data.items.length?data.items.map(item=>`<tr class="${item.archived?'is-archived':''}">
    <td><input class="manual-row-check" type="checkbox" data-key="${item.item_type}:${item.id}" aria-label="تحديد السجل ${item.id}"></td>
    <td><code>${esc(item.item_type)}:${item.id}</code>${item.parent_item_id?`<small>نسخة من #${item.parent_item_id}</small>`:''}</td>
    <td><strong>${esc(manualTypeLabels[item.item_type])}</strong><p>${esc(compact(item.preview,150))}</p></td>
    <td><span>${esc(languageLabels[item.language_layer]||item.language_layer||'—')}</span><small>${esc(item.domain||'—')}</small></td>
    <td><span>${esc(item.source||'—')}</span><small>${esc(item.origin||'—')}</small></td>
    <td><span>${fmtDate(item.created_at)}</span><small>${fmtDate(item.updated_at)}</small></td>
    <td><div class="status-stack"><span class="status-pill ${item.training_eligible_effective?'ok':'neutral'}">${item.training_eligible_effective?'مؤهل':'غير مؤهل'}</span>${item.archived?'<span class="status-pill archived">مؤرشف</span>':''}${item.exclude_from_training?'<span class="status-pill danger">مستبعد</span>':''}${item.exported_before?`<span class="status-pill exported">صُدّر سابقًا</span>`:''}</div></td>
    <td><bdi>v${item.version_number}</bdi></td>
    <td><div class="row-actions"><button data-action="view" data-type="${item.item_type}" data-id="${item.id}">عرض</button><button data-action="edit" data-type="${item.item_type}" data-id="${item.id}">تعديل</button><button data-action="clone" data-type="${item.item_type}" data-id="${item.id}">نسخ كنسخة جديدة</button><button data-action="archive" data-type="${item.item_type}" data-id="${item.id}">${item.archived?'إلغاء الأرشفة':'أرشفة'}</button><button data-action="exclude" data-type="${item.item_type}" data-id="${item.id}">${item.exclude_from_training?'إلغاء الاستبعاد':'استبعاد من التدريب'}</button><button data-action="ignore" data-type="${item.item_type}" data-id="${item.id}">تجاهل</button><button class="danger" data-action="delete" data-type="${item.item_type}" data-id="${item.id}">حذف</button></div></td>
  </tr>`).join(''):'<tr><td colspan="9"><div class="empty-inline">لا توجد عناصر تطابق الفلاتر الحالية.</div></td></tr>';
  $('#manual-select-all').checked=false;
}

function updateManualBulk(){
  $('#manual-selected-count').textContent=state.manualSelected.size;
  $('#manual-bulk').classList.toggle('hidden',!state.manualSelected.size);
}

function manualContent(item){
  if(item.item_type==='sft')return `<div class="chat-stream manual-chat">${(item.messages||[]).map(turn=>`<article class="message ${esc(turn.role)}"><span class="role">${turn.role==='user'?'المستخدم':turn.role==='assistant'?'المساعد':'System'}</span><p>${esc(turn.content)}</p></article>`).join('')}</div>`;
  if(item.item_type==='direct')return `<div class="full-text">${esc(item.text)}</div>`;
  const context=(item.prompt_context||[]).map(turn=>turn.content||'').join('\n');return `<div class="dpo-detail"><section><b>Prompt / Context</b><p>${esc(context)}</p></section><section class="rejected"><b>الرد المرفوض</b><p>${esc(item.rejected_response)}</p></section><section class="preferred"><b>الرد المفضل</b><p>${esc(item.preferred_response)}</p></section></div>`;
}

function manualStatusHtml(item){
  return `<span class="status-pill ${item.training_eligible_effective?'ok':'neutral'}">${item.training_eligible_effective?'مؤهل للتدريب':'غير مؤهل للتدريب'}</span>${item.archived?'<span class="status-pill archived">مؤرشف</span>':''}${item.exclude_from_training?'<span class="status-pill danger">مستبعد من التدريب</span>':''}${item.evaluation_only?'<span class="status-pill neutral">للتقييم فقط</span>':''}<span class="status-pill exported">Exported before: ${item.exported_before?'YES':'NO'}</span>`;
}

function renderManualDetails(item){
  const exported=item.exported_versions?.length?`<div class="export-history"><strong>نسخ Gold السابقة</strong>${item.exported_versions.map(v=>`<code>${esc(v)}</code>`).join('')}</div>`:'<div class="export-history muted">لم يُضمّن في نسخة Gold سابقة.</div>';
  $('#manual-tab-details').innerHTML=`
    <div class="detail-actions"><button class="button primary" data-detail-action="edit">تعديل</button><button class="button ghost" data-detail-action="eligibility">${item.training_eligible?'اجعل غير مؤهل':'اجعل مؤهلًا للتدريب'}</button><button class="button ghost" data-detail-action="clone">نسخ كنسخة جديدة</button><button class="button ghost" data-detail-action="archive">${item.archived?'إلغاء الأرشفة':'أرشفة'}</button><button class="button ghost" data-detail-action="exclude">${item.exclude_from_training?'إلغاء الاستبعاد':'استبعاد من التدريب'}</button><button class="button ghost" data-detail-action="ignore">تجاهل</button><button class="button danger-button" data-detail-action="delete">حذف</button></div>
    ${manualContent(item)}
    <dl class="detail-grid"><div><dt>طبقة اللغة</dt><dd>${esc(languageLabels[item.language_layer]||item.language_layer||'—')}</dd></div><div><dt>المجال</dt><dd>${esc(item.domain||'—')}</dd></div><div><dt>المصدر</dt><dd>${esc(item.source||'—')}</dd></div><div><dt>نوع المصدر</dt><dd>${esc(item.source_type||'—')}</dd></div><div><dt>الأصل</dt><dd>${esc(item.origin||'—')}</dd></div><div><dt>تاريخ الإنشاء</dt><dd>${fmtDate(item.created_at)}</dd></div><div><dt>آخر تعديل</dt><dd>${fmtDate(item.updated_at)}</dd></div><div><dt>النسخة الحالية</dt><dd>v${item.version_number}</dd></div><div><dt>Parent item</dt><dd>${item.parent_item_id?`#${item.parent_item_id}`:'—'}</dd></div><div class="wide"><dt>الملاحظات</dt><dd>${esc(item.notes||'—')}</dd></div></dl>${exported}`;
}

function option(value,label,current){return `<option value="${value}" ${value===current?'selected':''}>${label}</option>`;}
function commonManualFields(item){
  return `<div class="form-grid"><label>طبقة اللغة<select name="language_layer">${Object.entries(languageLabels).map(([v,l])=>option(v,l,item.language_layer)).join('')}</select></label><label>المجال<input name="domain" value="${esc(item.domain||'')}"></label><label>المصدر<input name="source" value="${esc(item.source||'')}"></label><label>نوع المصدر<select name="source_type">${[['human_written','مكتوب بشريًا'],['human_corrected','مصحح بشريًا'],['synthetic_reviewed','اصطناعي مراجع'],['external_licensed','خارجي مرخص']].map(([v,l])=>option(v,l,item.source_type)).join('')}</select></label><label>الأصل<select name="origin">${[['manual','يدوي'],['human_corrected','مصحح بشريًا'],['synthetic_reviewed','اصطناعي مراجع'],['ai_arena','AI Arena'],['imported','مستورد'],['real_conversation','محادثة حقيقية']].map(([v,l])=>option(v,l,item.origin)).join('')}</select></label></div><label class="wide-label">ملاحظات<textarea name="notes" rows="2">${esc(item.notes||'')}</textarea></label><div class="check-grid"><label><input name="training_eligible" type="checkbox" ${item.training_eligible?'checked':''}> مؤهل للتدريب</label><label><input name="evaluation_only" type="checkbox" ${item.evaluation_only?'checked':''}> للتقييم فقط</label><label><input name="exclude_from_training" type="checkbox" ${item.exclude_from_training?'checked':''}> مستبعد من التدريب</label><label><input name="archived" type="checkbox" ${item.archived?'checked':''}> مؤرشف</label></div><label class="wide-label">ملاحظة التعديل<textarea name="change_notes" rows="2" placeholder="ما الذي تغيّر؟"></textarea></label>`;
}

function renderManualEdit(item){
  let specific='';
  if(item.item_type==='sft')specific=`<div id="manual-edit-turns" class="turn-builder">${(item.messages||[]).map(turn=>manualTurnRow(turn.role,turn.content)).join('')}</div><button type="button" id="manual-add-turn" class="button ghost">＋ إضافة دور</button>`;
  else if(item.item_type==='direct')specific=`<label class="wide-label">النص<textarea name="text" rows="10" required>${esc(item.text)}</textarea></label>`;
  else specific=`<label class="wide-label">Prompt / Context<textarea name="prompt_context" rows="4" required>${esc((item.prompt_context||[]).map(x=>x.content||'').join('\n'))}</textarea></label><div class="preference-grid"><label>الرد المرفوض<textarea name="rejected_response" rows="7" required>${esc(item.rejected_response)}</textarea></label><label>الرد المفضل<textarea name="preferred_response" rows="7" required>${esc(item.preferred_response)}</textarea></label></div>`;
  $('#manual-tab-details').innerHTML=`<form id="manual-edit-form" class="manual-edit-form">${specific}${commonManualFields(item)}<div class="save-row"><button type="button" class="button ghost" data-detail-action="cancel-edit">إلغاء</button><button type="submit" class="button primary">حفظ</button></div></form>`;
  if(item.item_type==='sft')$('#manual-add-turn').addEventListener('click',()=>$('#manual-edit-turns').insertAdjacentHTML('beforeend',manualTurnRow('user','')));
  $('#manual-edit-form').addEventListener('click',e=>{if(e.target.matches('.remove-manual-turn'))e.target.closest('.turn-row').remove();});
  $('#manual-edit-form').addEventListener('submit',saveManualEdit);
}

function manualTurnRow(role,content){return `<div class="turn-row"><select class="turn-role">${option('user','User',role)}${option('assistant','Assistant',role)}${option('system','System',role)}</select><textarea class="turn-content">${esc(content)}</textarea><button class="remove-manual-turn" type="button" aria-label="حذف الدور">×</button></div>`;}

async function showManualItem(type,id,edit=false){
  const item=await api(`/api/v1/manual-data/${type}/${id}`);state.manualCurrent=item;
  $('#manual-dialog-kind').textContent=manualTypeLabels[type];$('#manual-dialog-title').textContent=`${type}:${id} · v${item.version_number}`;$('#manual-dialog-status').innerHTML=manualStatusHtml(item);
  renderManualDetails(item);$('#manual-tab-versions').innerHTML='<div class="empty-inline">افتح التبويب لتحميل سجل التعديلات.</div>';
  $$('.dialog-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.manualTab==='details'));$$('.manual-tab').forEach(x=>x.classList.toggle('active',x.id==='manual-tab-details'));
  if(edit)renderManualEdit(item);if(!$('#manual-dialog').open)$('#manual-dialog').showModal();
}

async function saveManualEdit(event){
  event.preventDefault();const item=state.manualCurrent,form=event.currentTarget,payload=formPayload(form);
  if(item.item_type==='sft')payload.messages=$$('#manual-edit-turns .turn-row').map(row=>({role:row.querySelector('.turn-role').value,content:row.querySelector('.turn-content').value}));
  const result=await api(`/api/v1/manual-data/${item.item_type}/${item.id}`,{method:'PATCH',body:JSON.stringify(payload)});state.manualCurrent=result.item;renderManualDetails(result.item);$('#manual-dialog-title').textContent=`${item.item_type}:${item.id} · v${result.item.version_number}`;$('#manual-dialog-status').innerHTML=manualStatusHtml(result.item);toast('تم حفظ نسخة جديدة في سجل التعديلات.');await loadManualData();
}

async function loadManualVersions(){
  const item=state.manualCurrent,data=await api(`/api/v1/manual-data/${item.item_type}/${item.id}/versions`);
  $('#manual-tab-versions').innerHTML=data.items.length?data.items.map(v=>`<article class="version-row"><div><strong>v${v.version_number}</strong><span>${fmtDate(v.created_at)} · ${v.changed_by==='human'?'human':'system'}</span></div><p>${esc(v.change_notes||'—')}</p><small>الحقول المتغيرة: ${esc(v.changed_fields.length?v.changed_fields.join('، '):'نسخة أساسية')}</small><button class="button ghost" data-version="${v.version_number}">عرض النسخة</button></article>`).join(''):'<div class="empty-inline">لا يوجد سجل نسخ.</div>';
  $('#manual-tab-versions').onclick=e=>{const button=e.target.closest('[data-version]');if(!button)return;const version=data.items.find(v=>v.version_number===Number(button.dataset.version));$('#manual-tab-versions').innerHTML=`<button id="back-to-versions" class="button ghost">← سجل التعديلات</button><div class="readonly-banner">نسخة للعرض فقط · v${version.version_number}</div><pre class="snapshot-view">${esc(JSON.stringify(version.snapshot,null,2))}</pre>`;$('#back-to-versions').onclick=loadManualVersions;};
}

async function manualAction(action,type,id){
  const item=state.manualItems.find(x=>x.item_type===type&&Number(x.id)===Number(id))||state.manualCurrent;
  if(action==='view'||action==='edit')return showManualItem(type,id,action==='edit');
  if(action==='clone'){await api(`/api/v1/manual-data/${type}/${id}/clone`,{method:'POST',body:'{}'});toast('تم إنشاء عنصر مستقل مع parent_item_id.');return loadManualData();}
  if(action==='archive'){await api(`/api/v1/manual-data/${type}/${id}/archive`,{method:'POST',body:JSON.stringify({archived:!item.archived})});toast(item.archived?'تم إلغاء الأرشفة.':'تمت الأرشفة.');}
  if(action==='exclude'){await api(`/api/v1/manual-data/${type}/${id}/exclude`,{method:'POST',body:JSON.stringify({excluded:!item.exclude_from_training})});toast(item.exclude_from_training?'تم إلغاء الاستبعاد.':'تم الاستبعاد من التدريب.');}
  if(action==='eligibility'){await api(`/api/v1/manual-data/${type}/${id}`,{method:'PATCH',body:JSON.stringify({training_eligible:!item.training_eligible,change_notes:'تغيير أهلية التدريب'})});toast('تم تحديث أهلية التدريب.');}
  if(action==='ignore'){
    await api(`/api/v1/manual-data/${type}/${id}/ignore`,{method:'POST',body:'{}'});toast('تم تجاهل السجل وحفظه للأرشيف.');$('#manual-dialog').close();
  }
  if(action==='delete'){
    if(item.exported_before&&!confirm(`هذا السجل سبق تضمينه في Dataset Version سابقة (${item.exported_versions.join('، ')}). لن تتغير أي نسخة قديمة. هل تريد المتابعة؟`))return;
    if(!confirm('حذف هذا السجل؟ لن يدخل في التدريب، وسيبقى محفوظًا في الأرشيف ويمكن استعادته مستقبلًا.'))return;
    await api(`/api/v1/manual-data/${type}/${id}`,{method:'DELETE',body:JSON.stringify({confirm_exported:item.exported_before})});toast('تم نقل السجل إلى المحذوفات؛ نسخ Gold القديمة لم تتغير.');$('#manual-dialog').close();
  }
  await loadManualData();if($('#manual-dialog').open&&action!=='delete')await showManualItem(type,id);
}

async function applyManualBulk(){
  const action=$('#manual-bulk-action').value;if(!action)return toast('اختر إجراءً جماعيًا.',true);
  const items=[...state.manualSelected].map(key=>{const [type,id]=key.split(':');return {type,id:Number(id)};});
  await api('/api/v1/manual-data/bulk',{method:'POST',body:JSON.stringify({action,items,change_notes:'تعديل جماعي من لوحة الإدارة'})});toast(`تم تحديث ${items.length} سجلًا.`);await loadManualData();
}

async function loadDataset(){
  const include=$('#dataset-demo').checked?'1':'0';const data=await api(`/api/v1/training-dataset?include_demo=${include}`);const labels={total:'الإجمالي',total_approved:'معتمد كما هو',full_corrections:'تصحيح كامل',dialect_corrections:'تصحيح لهجة',content_corrections:'تصحيح محتوى',manual_additions:'إضافات يدوية',multi_turn_conversations:'متعدد الأدوار',direct_language_texts:'نصوص مباشرة',preference_pairs:'أزواج تفضيل'};
  $('#dataset-stats').innerHTML=Object.entries(labels).map(([key,label])=>`<div class="stat-card"><span>${label}</span><strong>${data.stats[key]||0}</strong></div>`).join('');
  const items=[...data.reviews.map(i=>({...i,type:'مراجعة',preview:i.messages.at(-1)?.content})),...data.manual_sft.map(i=>({...i,type:'SFT يدوي',preview:i.messages?.at(-1)?.content})),...data.direct_language.map(i=>({...i,type:'نص مباشر',preview:i.text})),...data.preference_pairs.map(i=>({...i,type:'تفضيل',preview:i.preferred_response}))];
  $('#dataset-list').innerHTML=items.length?items.map(item=>`<div class="dataset-item"><span class="status-badge status-APPROVED">${esc(item.type)}</span><div><p>${esc(compact(item.preview,180))}</p><small>${esc(item.origin||'—')} · ${esc(item.language_layer||item.model_name||'—')} · ${esc(item.domain||'—')}</small></div><code>${esc(item.id)}</code></div>`).join(''):'<div class="empty-inline">لا توجد سجلات مؤهلة. الاعتماد البشري مطلوب أولًا.</div>';
}

async function previewDedup(){const include=$('#export-demo').checked?'1':'0';const [report,readiness]=await Promise.all([api(`/api/v1/exports/dedup-report?include_demo=${include}`),api(`/api/v1/exports/readiness?include_demo=${include}`)]);const blockers=readiness.blocking_findings||[];const gate=readiness.ok?'<br><strong>بوابة التصدير: جاهزة.</strong>':`<br><strong>بوابة التصدير: محجوبة.</strong> ${blockers.slice(0,3).map(item=>`${item.sample_id||'عام'}: ${item.reason}`).join('؛ ')}`;$('#dedup-result').innerHTML=`تم فحص <strong>${report.record_count}</strong> سجلًا: <strong>${report.exact_duplicate_groups.length}</strong> مجموعات مطابقة و<strong>${report.near_duplicates.length}</strong> حالات متشابهة. لا يتم حذف أي سجل تلقائيًا.${gate}`;toast(readiness.ok?'اكتمل فحص التكرار والجاهزية.':'اكتمل الفحص: توجد أسباب تمنع التصدير.',!readiness.ok);return readiness;}
async function createExport(){const button=$('#create-export');button.disabled=true;button.textContent='جارٍ إنشاء النسخة…';try{const readiness=await previewDedup();if(!readiness.ok)throw new Error('التصدير محجوب حتى معالجة أسباب المراجعة الظاهرة.');const result=await api('/api/v1/exports',{method:'POST',body:JSON.stringify({include_demo:$('#export-demo').checked,filters:{source:'dashboard'}})});toast(`تم إنشاء ${result.export.version} بنجاح.`);await loadExports();}catch(error){toast(error.message,true);}finally{button.disabled=false;button.textContent='إنشاء نسخة جديدة';}}
async function loadExports(){const data=await api('/api/v1/exports');$('#exports-list').innerHTML=data.items.length?data.items.map(item=>{let manifest={};try{manifest=JSON.parse(item.manifest_json);}catch{}return`<div class="export-row"><strong>${esc(item.version)}</strong><div><span>${fmtDate(item.created_at)} · ${item.record_count} سجل</span><br><code>${esc(item.export_path)}</code></div><span>${Object.keys(manifest.sha256||{}).length} checksums</span></div>`;}).join(''):'<div class="empty-inline">لم تُنشأ أي نسخة بعد.</div>';}

async function loadAnalytics(){const data=await api('/api/v1/analytics');const s=data.summary;const stats=[['إجمالي المحادثات',s.total_conversations],['إجمالي الردود',s.total_responses],['بانتظار المراجعة',s.pending_reviews],['نسبة الاعتماد',`${s.approved_pct}%`],['تصحيح اللهجة',`${s.dialect_corrections_pct}%`],['تصحيح المحتوى',`${s.content_corrections_pct}%`],['تصحيح كامل',`${s.full_corrections_pct}%`],['تم تجاهلها',s.ignored],['محذوفة',s.deleted],['مؤهل للتدريب',s.training_eligible_count]];$('#analytics-stats').innerHTML=stats.map(([label,value])=>`<div class="stat-card"><span>${label}</span><strong>${value??0}</strong></div>`).join('');$('#model-analytics').innerHTML=`<table class="analytics-table"><thead><tr><th>المودل</th><th>الردود</th><th>اعتماد</th><th>خطأ لهجة</th><th>خطأ محتوى</th></tr></thead><tbody>${data.by_model.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.total}</td><td>${x.approval_rate??0}%</td><td>${x.dialect_error_rate??0}%</td><td>${x.content_error_rate??0}%</td></tr>`).join('')}</tbody></table>`;renderBars('#channel-analytics',data.by_channel);renderBars('#tag-analytics',data.top_tags.map(x=>({...x,name:tagArabic[x.name]||x.name})));}
function renderBars(selector,items){const max=Math.max(1,...items.map(x=>x.count));$(selector).innerHTML=items.length?items.map(x=>`<div class="bar-item"><header><span>${esc(x.name||'غير محدد')}</span><strong>${x.count}</strong></header><div class="bar-track"><i style="width:${x.count/max*100}%"></i></div></div>`).join(''):'<div class="empty-inline">لا توجد بيانات بعد.</div>';}

