async function init(){try{$('#copyright-year').textContent=new Date().getFullYear();if(localStorage.getItem('najdilab.sidebar')==='collapsed'){$('.shell').classList.add('sidebar-collapsed');$('#collapse-sidebar').textContent='›';}await loadConfig();bindEvents();addSftTurn('user');addSftTurn('assistant');await loadQueue();const initial=pathViews[location.pathname]||'dashboard';switchView(initial,{fromHistory:true,replace:true,version:selectedVersion()});window.addEventListener('popstate',()=>switchView(pathViews[location.pathname]||'dashboard',{fromHistory:true,version:selectedVersion()}));}catch(error){toast(`تعذر بدء الواجهة: ${error.message}`,true);}}
function phase3Filtered(){const f=$('#phase3-filter')?.value||'all',records=state.phase3?.records||[];return records.filter(r=>f==='all'?true:f==='unreviewed'?!r.decision:f==='critical'?r.critical_fail:f==='text'||f==='tool'?r.evaluation_type===f:r.decision===f);}
const phase3Term={ADAPTER_WIN:'فوز المحوّل',BASE_WIN:'فوز الأساس',TIE:'تعادل',NONE:'بلا شدة',MINOR:'طفيف',MAJOR:'جسيم',CRITICAL:'حرج',text:'نصي',tool:'أدوات',RECOMMEND_REJECT:'يوصى بالرفض',RECOMMEND_APPROVE:'يوصى بالاعتماد',RECOMMEND_RETRAINING:'يوصى بإعادة التدريب',REJECT:'رفض',APPROVE:'اعتماد',NEEDS_RETRAINING:'تحتاج إعادة تدريب',BLOCKED:'محظورة',READY:'جاهزة'};
const phase3DimensionArabic={content_correctness:'صحة المحتوى',instruction_following:'اتباع التعليمات',constraint_adherence:'الالتزام بالقيود',najdi_saudi_dialect:'اللهجة النجدية/السعودية',natural_arabic:'طبيعية العربية',context_handling:'فهم السياق',multi_turn_behavior:'سلوك المحادثة متعددة الأدوار',relevance:'الصلة',conciseness:'الإيجاز',repetition:'التكرار',hallucination:'الهلوسة',tool_behavior:'سلوك الأدوات',overall_usefulness:'الفائدة العامة'};
function phase3Prompt(messages){return (messages||[]).map(m=>`<div class="message ${esc(m.role)}"><span class="role">${phase38Roles[m.role]||esc(m.role)}</span><p>${esc(m.content)}</p></div>`).join('');}
function renderPhase3(){const data=state.phase3,s=data.summary,filtered=phase3Filtered();state.phase3Index=Math.max(0,Math.min(state.phase3Index,Math.max(0,filtered.length-1)));$('#phase3-progress').innerHTML=[['Reviewed',`${s.reviewed} / ${s.total}`],['Adapter Wins',s.adapter_wins],['Base Wins',s.base_wins],['Ties',s.ties],['Adapter Minor Regressions',s.adapter_minor_regressions],['Adapter Major Regressions',s.adapter_major_regressions],['Adapter Critical Regressions',s.adapter_critical_regressions],['Base Major Failures',s.base_major_failures],['Base Critical Failures',s.base_critical_failures]].map(x=>`<div class="stat-card"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('');if(!filtered.length){$('#phase3-case').innerHTML='<div class="empty-inline">لا توجد حالات في هذا الفلتر.</div>';$('#phase3-controls').innerHTML='';return;}const r=filtered[state.phase3Index],blind=$('#phase3-blind').checked,swap=[...r.eval_id].reduce((a,c)=>a+c.charCodeAt(0),0)%2===1,first=swap?r.adapter_response:r.base_response,second=swap?r.base_response:r.adapter_response;$('#phase3-case').innerHTML=`<div class="panel-heading"><div><span class="eyebrow">${esc(r.evaluation_type)} · ${esc(r.category||'—')}</span><h2>${esc(r.eval_id)} · ${state.phase3Index+1}/${filtered.length}</h2></div><span class="gate-badge ${r.decision?'pass':'unavailable'}">${esc(r.decision||'UNREVIEWED')}</span></div><h3>Prompt</h3><div class="phase3-prompt chat-stream">${phase3Prompt(r.prompt)}</div><div class="phase3-compare"><article><h3>Gold</h3><pre>${esc(r.gold_response)}</pre></article><article><h3>${blind?'Response A':swap?'Adapter':'Base'}</h3><pre>${esc(first)}</pre></article><article><h3>${blind?'Response B':swap?'Base':'Adapter'}</h3><pre>${esc(second)}</pre></article></div><div class="diagnostic-note"><b>Diagnostic only</b> · Base ${r.diagnostic.base_similarity} · Adapter ${r.diagnostic.adapter_similarity} · Δ ${r.diagnostic.delta}</div>`;const labels=blind?[{v:swap?'ADAPTER_WIN':'BASE_WIN',t:'Response A أفضل'},{v:'TIE',t:'متعادل'},{v:swap?'BASE_WIN':'ADAPTER_WIN',t:'Response B أفضل'}]:[{v:'ADAPTER_WIN',t:'Adapter أفضل'},{v:'TIE',t:'متعادل'},{v:'BASE_WIN',t:'Base أفضل'}];const tags=['instruction_following','factual_error','hallucination','dialect_issue','unnatural_arabic','repetition','verbosity','too_short','context_failure','constraint_failure','tool_behavior','formatting','safety','other'];const dims=['content_correctness','instruction_following','constraint_adherence','najdi_saudi_dialect','natural_arabic','context_handling','multi_turn_behavior','relevance','conciseness','repetition','hallucination','tool_behavior','overall_usefulness'];$('#phase3-controls').innerHTML=`<h2>الحكم البشري</h2><div class="phase3-decisions">${labels.map(x=>`<button class="button ${r.decision===x.v?'primary':'ghost'}" data-phase3-decision="${x.v}">${x.t}</button>`).join('')}</div><label class="wide-label">Severity<select id="phase3-severity"><option>NONE</option><option>MINOR</option><option>MAJOR</option><option>CRITICAL</option></select></label><label class="inline-check critical-check"><input id="phase3-critical" type="checkbox" ${r.critical_fail?'checked':''}> Critical Fail — خطأ جوهري، هلوسة مؤثرة، قيد أساسي متجاهل، tool behavior خطر، أو regression شديد</label><div class="field"><label>وسوم الخطأ</label><div class="tag-picker phase3-tags">${tags.map(t=>`<button type="button" class="${r.error_tags.includes(t)?'selected':''}" data-phase3-tag="${t}">${t}</button>`).join('')}</div></div><details><summary>درجات الأبعاد الاختيارية</summary><div class="phase3-dimensions">${dims.map(d=>`<label>${d}<select data-phase3-dimension="${d}"><option value="">—</option><option value="0">0</option><option value="1">1</option><option value="2">2</option></select></label>`).join('')}</div></details><label class="wide-label">ملاحظات<textarea id="phase3-notes" rows="4">${esc(r.notes)}</textarea></label><div class="save-row"><button class="button ghost" data-phase3-nav="prev">السابق</button><button class="button ghost" data-phase3-skip>تخطي مؤقتًا</button><button class="button primary" data-phase3-save>حفظ</button><button class="button ghost" data-phase3-nav="next">التالي</button></div>`;$('#phase3-severity').value=r.severity;$$('[data-phase3-dimension]').forEach(x=>x.value=r.dimension_scores[x.dataset.phase3Dimension]??'');const summary=data.summary;$('#phase3-summary').innerHTML=`<div class="panel-heading"><div><span class="eyebrow">Human Review Summary</span><h2>${data.review_status}</h2></div><span class="gate-badge ${data.final_gate.phase4a==='READY'?'pass':'blocked'}">Phase 4A ${data.final_gate.phase4a}</span></div><p>Recommendation: <b>${esc(summary.recommendation||'تظهر بعد اكتمال 24/24')}</b> — تشخيصية فقط.</p>${summary.remaining===0&&data.final_gate.final_decision==null?`<div class="final-gate"><p>كل الحالات محسومة. القرار النهائي لا يبدأ Phase 4 تلقائيًا.</p><button class="button primary" data-phase3-final="APPROVE">APPROVE</button><button class="button ghost" data-phase3-final="NEEDS_RETRAINING">NEEDS RETRAINING</button><button class="button ghost" data-phase3-final="REJECT">REJECT</button></div>`:''}`;}
const renderPhase3Core=renderPhase3;
renderPhase3=function(){renderPhase3Core();const s=state.phase3?.summary,host=$('#phase3-summary');if(!s||!host)return;const tags=Object.entries(s.tag_frequency||{}).sort((a,b)=>b[1]-a[1]);const breakdown=Object.entries(s.breakdown||{});const cross=s.winner_severity_cross_tab||{};host.insertAdjacentHTML('beforeend',`<div class="phase3-summary-grid"><span>Win rate<b>${(s.win_rate*100).toFixed(1)}%</b></span><span>Regression rate<b>${(s.regression_rate*100).toFixed(1)}%</b></span><span>Critical cases (global)<b>${s.critical_cases}</b></span><span>Tie Critical Cases<b>${s.tie_critical_cases}</b></span></div><details><summary>تفاصيل الملخص</summary><p><b>Winner × Severity:</b> ${Object.entries(cross).map(([winner,severity])=>`${esc(winner)} — NONE ${severity.NONE||0}, MINOR ${severity.MINOR||0}, MAJOR ${severity.MAJOR||0}, CRITICAL ${severity.CRITICAL||0}`).join('<br>')}</p><p><b>Tag frequency:</b> ${tags.length?tags.map(([k,v])=>`${esc(k)} (${v})`).join(' · '):'—'}</p><p><b>Breakdown:</b> ${breakdown.length?breakdown.map(([k,v])=>`${esc(k)}: A ${v.ADAPTER_WIN||0} / T ${v.TIE||0} / B ${v.BASE_WIN||0}`).join(' · '):'—'}</p></details>`);};
function localizePhase3Dom(){
  const stats={'Reviewed':'تمت المراجعة','Adapter Wins':'انتصارات المحوّل','Base Wins':'انتصارات الأساس','Ties':'التعادلات','Adapter Minor Regressions':'تراجعات المحوّل الطفيفة','Adapter Major Regressions':'تراجعات المحوّل الجسيمة','Adapter Critical Regressions':'تراجعات المحوّل الحرجة','Base Major Failures':'إخفاقات الأساس الجسيمة','Base Critical Failures':'إخفاقات الأساس الحرجة','Win rate':'نسبة فوز المحوّل','Regression rate':'نسبة التراجع','Critical cases (global)':'الحالات الحرجة إجمالًا','Tie Critical Cases':'حالات التعادل الحرجة'};
  $$('#view-human-review .stat-card span, #phase3-summary .phase3-summary-grid span').forEach(x=>{for(const [en,ar] of Object.entries(stats))if(x.firstChild?.nodeValue?.trim()===en)x.firstChild.nodeValue=ar;});
  $$('#phase3-severity option').forEach(x=>x.textContent=phase3Term[x.value]||x.textContent);$$('[data-phase3-tag]').forEach(x=>x.textContent=tagArabic[x.dataset.phase3Tag]||x.dataset.phase3Tag);$$('[data-phase3-dimension]').forEach(x=>{x.parentElement.firstChild.nodeValue=phase3DimensionArabic[x.dataset.phase3Dimension]||x.dataset.phase3Dimension;});
  $$('#phase3-case h3').forEach(x=>{if(x.textContent==='Prompt')x.textContent='المطالبة';else if(x.textContent==='Gold')x.textContent='الإجابة المرجعية';});
  const summary=$('#phase3-summary');if(summary){summary.querySelectorAll('p,summary').forEach(x=>{x.childNodes.forEach(n=>{if(n.nodeType===Node.TEXT_NODE)n.nodeValue=n.nodeValue.replace('Recommendation:','التوصية:').replace('Diagnostic only','تشخيصي فقط').replace('Winner × Severity:','الفائز × الشدة:').replace('Tag frequency:','تكرار الوسوم:').replace('Breakdown:','التوزيع:');});});}
}
const renderPhase3LocalizedBase=renderPhase3;renderPhase3=function(){renderPhase3LocalizedBase();localizePhase3Dom();};
async function loadPhase3ReviewLegacy(){state.phase3=await api('/api/v1/phase3/phase3-train-20261006-001/human-review');renderPhase3();}

async function loadPhase3Review(){
  state.phase3=await api('/api/v1/phase3/phase3-train-20261006-001/human-review'); state.phase3Dirty=false; renderPhase3();
  if(state.phase3Bound)return; state.phase3Bound=true;
  const leaveCase=direction=>{if(state.phase3Dirty&&!confirm('لديك تعديلات غير محفوظة. هل تريد الانتقال وفقدها؟'))return;const list=phase3Filtered();state.phase3Index=Math.max(0,Math.min(list.length-1,state.phase3Index+direction));state.phase3Dirty=false;renderPhase3();};
  $('#phase3-filter').addEventListener('change',()=>{if(state.phase3Dirty&&!confirm('لديك تعديلات غير محفوظة. هل تريد تغيير الفلتر وفقدها؟'))return;state.phase3Index=0;state.phase3Dirty=false;renderPhase3();});
  $('#phase3-blind').addEventListener('change',()=>{state.phase3Dirty=false;renderPhase3();});
  $('#view-human-review').addEventListener('change',e=>{if(e.target.closest('#phase3-controls'))state.phase3Dirty=true;});
  $('#view-human-review').addEventListener('input',e=>{if(e.target.closest('#phase3-controls'))state.phase3Dirty=true;});
  $('#view-human-review').addEventListener('click',async e=>{
    const d=e.target.closest('[data-phase3-decision]'),tag=e.target.closest('[data-phase3-tag]'),nav=e.target.closest('[data-phase3-nav]'),skip=e.target.closest('[data-phase3-skip]'),save=e.target.closest('[data-phase3-save]'),final=e.target.closest('[data-phase3-final]');
    if(d){$$('[data-phase3-decision]').forEach(x=>x.classList.toggle('primary',x===d));$$('[data-phase3-decision]').forEach(x=>x.classList.toggle('ghost',x!==d));state.phase3Dirty=true;return;}
    if(tag){tag.classList.toggle('selected');state.phase3Dirty=true;return;}
    if(nav||skip){leaveCase(nav?.dataset.phase3Nav==='prev'?-1:1);return;}
    if(save){
      const r=phase3Filtered()[state.phase3Index],chosen=$('[data-phase3-decision].primary');
      if(!chosen)return toast('اختر الحكم الإلزامي أولًا.',true);
      const buttons=$$('[data-phase3-decision]'),choiceIndex=buttons.indexOf(chosen),body={severity:$('#phase3-severity').value,critical_fail:$('#phase3-critical').checked,error_tags:$$('[data-phase3-tag].selected').map(x=>x.dataset.phase3Tag),dimension_scores:Object.fromEntries($$('[data-phase3-dimension]').filter(x=>x.value!=='').map(x=>[x.dataset.phase3Dimension,Number(x.value)])),notes:$('#phase3-notes').value};
      if($('#phase3-blind').checked)body.blind_choice=['A','TIE','B'][choiceIndex];else body.decision=chosen.dataset.phase3Decision;
      save.disabled=true;save.textContent='جارٍ الحفظ…';
      try{const out=await api(`/api/v1/phase3/phase3-train-20261006-001/human-review/cases/${encodeURIComponent(r.eval_id)}`,{method:'POST',body:JSON.stringify(body)});state.phase3=out.review;state.phase3Dirty=false;renderPhase3();toast('تم الحفظ');}
      catch(error){save.disabled=false;save.textContent='حفظ';toast(`تعذر الحفظ: ${error.message}`,true);}
      return;
    }
    if(final){if(!confirm(`تسجيل القرار النهائي ${final.dataset.phase3Final}؟ لن يبدأ Phase 4 تلقائيًا.`))return;try{const out=await api('/api/v1/phase3/phase3-train-20261006-001/human-review/final-decision',{method:'POST',body:JSON.stringify({decision:final.dataset.phase3Final})});state.phase3=out.review;renderPhase3();toast('سُجل القرار النهائي دون بدء Phase 4.');}catch(error){toast(`تعذر تسجيل القرار: ${error.message}`,true);}}
  });
}

const phase38Criteria={factual_correctness:'الصحة الواقعية',instruction_following:'اتباع التعليمات',dialect_quality:'جودة اللهجة',natural_arabic:'طبيعية العربية',concision:'الإيجاز',context_continuity:'استمرارية السياق',tool_correctness:'صحة استخدام الأدوات',hallucination_risk:'خطر الهلوسة',repetition_risk:'خطر التكرار',contamination_concern:'شبهة تلوث التقييم'};
const phase38Coverage={instruction_following:'اتباع التعليمات',verbosity_focus:'ضبط الإطالة',constraint_following:'اتباع القيود',tool_behavior:'سلوك الأدوات',capability_understanding:'فهم القدرات',fabricated_tool_prevention:'منع ادعاء تنفيذ الأدوات',hallucination_prevention:'منع الهلوسة',context_understanding:'فهم السياق',conversational_continuity:'استمرارية الحوار',najdi_saudi_dialect:'اللهجة السعودية/النجدية',natural_arabic:'عربية طبيعية',repetition_prevention:'منع التكرار',factual_accuracy:'الدقة الواقعية'};
const phase38Types={sft:'محادثة قصيرة (SFT)',multi_turn:'محادثة متعددة الأدوار',native_tool_use:'استخدام أداة أصلي'};
const phase38Roles={system:'النظام',user:'المستخدم',assistant:'المساعد',tool:'نتيجة الأداة'};

function phase38Validate(data){
  if(!data||!Array.isArray(data.records))throw new Error('استجابة المراجعة لا تحتوي سجلات صالحة');
  const counts=data.records.reduce((a,r)=>(a[r.record_type]=(a[r.record_type]||0)+1,a),{});
  if(data.records.length!==36||counts.sft!==12||counts.multi_turn!==16||counts.native_tool_use!==8)throw new Error('توزيع السجلات غير مطابق للمتوقع: 12 قصيرة، 16 متعددة الأدوار، 8 أدوات');
  if(data.records.some(r=>r.record?.provenance?.kind!=='new_remediation'))throw new Error('عُثر على سجل غير جديد في طابور Phase 3.8');
  if(data.records.some(r=>/holdout|eval/i.test(r.record_id||'')))throw new Error('حماية التسرب أوقفت عرض سجل يبدو تابعًا للتقييم المحجوز');
}
function phase38Messages(messages){return (messages||[]).map((m,i)=>{const calls=(m.tool_calls||[]).map(c=>`<div class="phase38-tool-call"><b>استدعاء أداة</b><div class="technical-id">${esc(c.function?.name||'—')}</div><pre>${esc(c.function?.arguments||'')}</pre></div>`).join('');const result=m.role==='tool'?`<div class="phase38-tool-result"><b>نتيجة موثوقة للقراءة فقط</b><pre>${esc(typeof m.content==='string'?m.content:JSON.stringify(m.content,null,2))}</pre></div>`:'';return `<article class="phase38-message ${esc(m.role)}"><span class="role">${phase38Roles[m.role]||esc(m.role)} · ${i+1}</span>${m.role==='tool'?'':`<p>${esc(m.content||'')}</p>`}${calls}${result}</article>`;}).join('');}
function phase38EditFields(record){
  if(state.phase38Decision!=='EDIT')return '';
  const assistants=(record.record?.messages||[]).map((m,i)=>({m,i})).filter(x=>x.m.role==='assistant'&&x.m.content!==undefined);
  const editable=record.record_type==='native_tool_use'?assistants.slice(-1):assistants;
  const proposed=record.review?.proposed_assistant_edits||{};
  return `<div class="phase38-edit-fields"><h3>التعديل المقترح</h3>${record.record_type==='native_tool_use'?'<p class="readonly-tool-note">استدعاءات الأدوات ونتائجها للقراءة فقط؛ يمكن تعديل رد المساعد النهائي فقط.</p>':''}${editable.map(({m,i})=>`<label class="wide-label">رد المساعد رقم ${i+1}<textarea data-phase38-edit-index="${i}" rows="5">${esc(proposed[i]??m.content??'')}</textarea></label>`).join('')}</div>`;
}
function renderPhase38(){
  const data=state.phase38,s=data.summary,r=data.records[state.phase38Index];
  $('#nav-phase38').textContent=`${s.reviewed}/${s.total}`;
  $('#phase38-status').classList.add('hidden');$('#phase38-workspace').classList.remove('hidden');
  const coverage=(r.record?.coverage||[]).map(x=>`<span title="${esc(x)}">${esc(phase38Coverage[x]||x)}</span>`).join('');
  $('#phase38-record').innerHTML=`<div class="phase38-record-head"><div><span class="eyebrow">${esc(phase38Types[r.record_type]||r.record_type)}</span><h2 class="technical-id">${esc(r.record_id)}</h2><p>السجل ${state.phase38Index+1} من ${data.records.length}</p></div><span class="gate-badge ${r.decision?'pass':'unavailable'}">${r.decision==='APPROVE'?'معتمد':r.decision==='EDIT'?'يحتاج تعديلًا':r.decision==='REJECT'?'مرفوض':'بانتظار القرار'}</span></div><div class="coverage-chips">${coverage}</div><div class="phase38-messages">${phase38Messages(r.record?.messages)}</div><details class="phase38-technical"><summary>التفاصيل التقنية</summary><pre>${esc(JSON.stringify({record_type:r.record_type,conversation_id:r.record?.conversation_id,target_message_index:r.record?.target_message_index,message_loss_mask:r.record?.message_loss_mask,train_on_last_assistant_only:r.record?.train_on_last_assistant_only,tool_contract:r.tool_view?{capability_registry:r.tool_view.capability_registry,visible_tools:r.tool_view.visible_tools,loss_mask_preview:r.tool_view.loss_mask_preview}:null},null,2))}</pre></details>`;
  $('#phase38-summary').innerHTML=`<span>تمت المراجعة<b>${s.reviewed}/${s.total}</b></span><span>معتمد<b>${s.approved}</b></span><span>تعديل<b>${s.edited}</b></span><span>مرفوض<b>${s.rejected}</b></span><span>متبقي<b>${s.remaining}</b></span><span>النوع<b>${esc(r.record_type)}</b></span>`;
  $('#phase38-criteria').innerHTML=Object.entries(phase38Criteria).map(([key,label])=>`<label>${label}<select data-phase38-field="${key}"><option value="">غير محدد</option><option value="PASS">سليم</option><option value="FAIL">يحتاج معالجة</option><option value="NA">لا ينطبق</option></select></label>`).join('');
  $$('[data-phase38-field]').forEach(x=>x.value=r.review?.[x.dataset.phase38Field]??'');$('#phase38-notes').value=r.review?.notes||'';
  state.phase38Decision=r.decision;$$('[data-phase38-decision]').forEach(x=>x.classList.toggle('selected',x.dataset.phase38Decision===state.phase38Decision));
  $('#phase38-edit-fields').innerHTML=phase38EditFields(r);$('#phase38-save').disabled=!state.phase38Decision;$('#phase38-save').textContent='حفظ القرار';$('#phase38-save-state').className='save-state';$('#phase38-save-state').textContent=state.phase38Dirty?'توجد تغييرات غير محفوظة.':'';
}
function showPhase38Error(message){$('#phase38-workspace').classList.add('hidden');const host=$('#phase38-status');host.className='panel phase38-status error-state';host.innerHTML=`<strong>تعذر تحميل مراجعة Phase 3.8</strong><p>${esc(message)}</p><button id="phase38-retry" class="button primary">إعادة المحاولة</button>`;$('#phase38-retry').onclick=loadPhase38Review;}
async function loadPhase38Review(){
  const host=$('#phase38-status');host.className='panel phase38-status';host.textContent='جارٍ تحميل 36 سجلًا جديدًا…';host.classList.remove('hidden');$('#phase38-workspace').classList.add('hidden');
  try{const data=await api('/api/v1/phase38/v009/human-review');phase38Validate(data);state.phase38=data;state.phase38Dirty=false;state.phase38Index=Math.min(state.phase38Index,35);renderPhase38();if(!state.phase38Bound)bindPhase38();}
  catch(error){showPhase38Error(error.message);}
}
function phase38Navigate(delta){if(state.phase38Dirty&&!confirm('لديك تغييرات غير محفوظة. هل تريد الانتقال وفقدها؟'))return;state.phase38Index=Math.max(0,Math.min(35,state.phase38Index+delta));state.phase38Dirty=false;renderPhase38();}
function bindPhase38(){
  state.phase38Bound=true;const view=$('#view-phase38-review');
  view.addEventListener('input',e=>{if(e.target.matches('textarea,[data-phase38-field]')){state.phase38Dirty=true;$('#phase38-save-state').textContent='توجد تغييرات غير محفوظة.';}});
  view.addEventListener('change',e=>{if(e.target.matches('[data-phase38-field]'))state.phase38Dirty=true;});
  view.addEventListener('click',async e=>{const decision=e.target.closest('[data-phase38-decision]'),nav=e.target.closest('[data-phase38-nav]');if(nav){phase38Navigate(nav.dataset.phase38Nav==='prev'?-1:1);return;}if(decision){state.phase38Decision=decision.dataset.phase38Decision;state.phase38Dirty=true;$$('[data-phase38-decision]').forEach(x=>x.classList.toggle('selected',x===decision));$('#phase38-edit-fields').innerHTML=phase38EditFields(state.phase38.records[state.phase38Index]);$('#phase38-save').disabled=false;$('#phase38-save-state').textContent='توجد تغييرات غير محفوظة.';return;}if(!e.target.closest('#phase38-save'))return;
    const button=$('#phase38-save'),r=state.phase38.records[state.phase38Index],review={notes:$('#phase38-notes').value};$$('[data-phase38-field]').forEach(x=>review[x.dataset.phase38Field]=x.value||null);if(state.phase38Decision==='EDIT')review.proposed_assistant_edits=Object.fromEntries($$('[data-phase38-edit-index]').map(x=>[x.dataset.phase38EditIndex,x.value]));button.disabled=true;button.textContent='جارٍ الحفظ…';state.phase38Saving=true;
    try{const out=await api(`/api/v1/phase38/v009/human-review/${encodeURIComponent(r.record_id)}`,{method:'POST',body:JSON.stringify({decision:state.phase38Decision,review})});phase38Validate(out.review);state.phase38=out.review;state.phase38Dirty=false;state.phase38Saving=false;renderPhase38();$('#phase38-save-state').className='save-state success';$('#phase38-save-state').textContent='تم حفظ القرار بنجاح.';toast('تم حفظ مراجعة السجل.');}
    catch(error){state.phase38Saving=false;button.disabled=false;button.textContent='إعادة محاولة الحفظ';$('#phase38-save-state').className='save-state error';$('#phase38-save-state').textContent=`تعذر الحفظ: ${error.message}`;}
  });
  window.addEventListener('beforeunload',e=>{if(state.phase38Dirty){e.preventDefault();e.returnValue='';}});
}

const showTrainingJobWithoutRecovery=showTrainingJob;
showTrainingJob=async function(jobId){await showTrainingJobWithoutRecovery(jobId);const j=await api(`/api/v1/training/jobs/${encodeURIComponent(jobId)}`);if(j.provenance?.recovery){const host=$('#training-job-detail .version-summary');host?.insertAdjacentHTML('afterend',`<section class="execution-readiness"><div class="panel-heading"><h3>Phase 2-C Recovery</h3><span class="gate-badge pass">FIX APPLIED</span></div><div class="readiness-grid"><span>attempt-001<b>FAILED</b></span><span>Reason<b>max_steps mapping / Trainer plan mismatch</b></span><span>checkpoint-1<b>NON_RESUMABLE</b></span><span>attempt-002<b>${esc(j.full_training_status||'—')} · FROM SCRATCH</b></span></div></section>`);}};
